"use client";
import LegacyPage from "../components/LegacyPage";

const TITLE = "Averages — Messages";
const STYLE_CSS = "\n  /* ---------- Shared design system — copied verbatim from /grades so\n     this page reads as the same app, not a reskin. Grade-color tokens\n     (--grade-good etc.) aren't needed here and are left out. See\n     architecture-decisions.md for the note about promoting this to an\n     actual shared stylesheet once there's a build step. ---------- */\n  :root {\n    --accent: #d94a2b;\n    --accent-dark: #a8331a;\n    --accent-ring: rgb(from var(--accent) r g b / 0.35);\n    --page-bg-start: #f17b53;\n    --page-bg-end: #930500;\n    --panel-bg: #eaeaec;\n    --panel-inner: #dcdce0;\n    --text-dark: #14151f;\n    --text-muted: #4b4d63;\n    --text-faint: #83849a;\n    --border: #cfcfd6;\n    --window-radius-lg: 22px;\n    --window-radius-md: 14px;\n    --window-radius-sm: 10px;\n  }\n\n  * { box-sizing: border-box; }\n\n  /* Scrollbars app-wide: a slim, permanently-visible, rounded gray bar\n     sitting slightly inset from the true edge of its scrollable area --\n     like a normal OS/Gmail-style scrollbar, not hidden and not\n     hover-gated. (An earlier hover-only version turned out unreliable:\n     the outer page counts as \"hovered\" almost the entire time you're\n     using it, so it either showed constantly or never, depending on the\n     browser -- not the meaningful hover signal it needed to be.)\n     Scrolling itself always works via wheel/trackpad/touch/keys either\n     way. One universal rule (the `*` selector) so it covers every\n     scrollable element automatically — the outer page scroll, every\n     popup/modal, every internal list — without repeating it per\n     element. (The bottom nav's own horizontal scroll strip is a\n     deliberate exception — see .app-nav-inner further down — that one\n     stays permanently hidden as a mobile overflow safety net.) */\n  * {\n    scrollbar-width: thin;\n    scrollbar-color: rgba(20, 21, 31, 0.28) transparent;\n  }\n  *::-webkit-scrollbar { width: 10px; height: 10px; }\n  *::-webkit-scrollbar-track { background: transparent; }\n  *::-webkit-scrollbar-thumb {\n    background-color: rgba(20, 21, 31, 0.28);\n    border-radius: 999px;\n    border: 2px solid transparent;\n    background-clip: padding-box; /* the transparent border creates the\n      inset gap around the thumb, so it reads as sitting inside the\n      window rather than flush against the very edge */\n  }\n  *::-webkit-scrollbar-thumb:hover { background-color: rgba(20, 21, 31, 0.45); }\n  *::-webkit-scrollbar-corner { background: transparent; }\n\n  /* Declared so the browser themes ITS OWN chrome — scrollbars, the\n\n     overscroll gutter, form controls — against this page rather than\n\n     guessing. Without it Firefox drew a light-theme scrollbar over the\n\n     dark canvas and tinted it (Martin saw it as pink on a blue\n\n     background). LegacyPage's applyStoredTheme() updates both of these\n\n     to match whatever background the user actually saved. */\n\n  html {\n\n    color-scheme: dark;\n\n    background-color: #0c0c0e;\n\n  }\n\n\n  html, body {\n    margin: 0;\n    padding: 0;\n    min-height: 100%;\n    font-family: \"puffin\", -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, Helvetica, Arial, sans-serif;\n  }\n\n  body {\n    height: 100vh; /* fixed, not min -- body itself no longer scrolls */\n    overflow: hidden; /* scrolling now happens inside .page (see below), so\n      the scrollbar sits at the edge of the app's own window/card instead of\n      out at the browser's outer edge, over the wallpaper margin */\n    /* Neutral black instead of a baked-in accent gradient here —\n       2026-09-11, per Martin. This is only ever visible for a split\n       second on reload/navigation, before applyStoredTheme() (or this\n       page's own appearance-reading script) sets the user's actual\n       saved background over it. The old default was the sample\n       red-orange gradient baked into this file, which read as a real\n       glitch flashing in between pages; a neutral black reads as\n       \"still loading\" instead, and matches the app's own Black\n       preset (#0c0c0e) so it's not a color that appears nowhere else\n       in the app. */\n    background-color: #0c0c0e;\n    background-image: none;\n    background-size: cover;\n    background-position: center;\n    background-repeat: no-repeat;\n    padding: 40px 24px 100px;\n    display: flex;\n    justify-content: center;\n  }\n\n  .page {\n    width: 100%;\n    max-width: 980px;\n    align-self: stretch; /* fill body's available height regardless of\n      whatever align-items body declares, so there's a bounded box to\n      scroll within */\n    min-height: 0; /* flexbox gotcha: without this, a flex item won't\n      shrink below its content size, which breaks overflow scrolling */\n    overflow-y: auto; /* kept as a fallback; in practice .msgs-shell\n      below is height-capped and scrolls its own content internally\n      (see .msgs-thread-list / .msgs-bubbles / etc.), so this almost\n      never actually engages. Messages-specific (2026-09-04, per\n      Martin): unlike the other pages in this app, a chat UI's list\n      and conversation panes should behave like a real messaging app\n      -- fixed header/search/composer chrome, only the middle scrolls\n      -- so this page keeps the windowed pattern the rest of the app\n      moved away from. */\n    overflow-x: hidden;\n    display: flex;\n    flex-direction: column;\n  }\n\n  /* ---------- Top bar — copied verbatim ---------- */\n  .topbar {\n    display: flex;\n    align-items: flex-end;\n    justify-content: space-between;\n    margin: 0 4px 18px;\n  }\n  h1.title {\n    color: #ffffff;\n    font-size: clamp(1.6rem, 3.4vw, 2.1rem);\n    font-weight: 900;\n    font-style: italic;\n    letter-spacing: -0.01em;\n    margin: 0;\n    transform: skewX(-2deg);\n    display: inline-block;\n  }\n  .subtitle {\n    color: rgba(255,255,255,0.85);\n    font-weight: 700;\n    font-style: italic;\n    font-size: 0.9rem;\n    margin: 2px 0 0 2px;\n  }\n  .profile-menu-wrap { position: relative; flex-shrink: 0; }\n  .profile-btn {\n    width: 42px;\n    height: 42px;\n    border-radius: 50%;\n    background: rgba(255,255,255,0.2);\n    border: 2px solid rgba(255,255,255,0.5);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    color: #fff;\n    font-weight: 800;\n    font-size: 0.95rem;\n    cursor: pointer;\n    flex-shrink: 0;\n  }\n  .profile-menu {\n    position: absolute;\n    top: calc(100% + 10px);\n    right: 0;\n    min-width: 160px;\n    background: var(--panel-bg);\n    border-radius: var(--window-radius-md);\n    box-shadow: 0 20px 45px -16px rgba(0,0,0,0.5);\n    padding: 6px;\n    z-index: 25;\n  }\n  .profile-menu-item {\n    display: block;\n    width: 100%;\n    text-align: left;\n    background: none;\n    border: none;\n    border-radius: var(--window-radius-sm);\n    font: inherit;\n    font-weight: 700;\n    font-size: 0.86rem;\n    color: var(--text-dark);\n    padding: 9px 12px;\n    cursor: pointer;\n  }\n  .profile-menu-item:hover { background: var(--panel-inner); }\n  .profile-menu-item.signout { color: #b6432f; }\n\n  /* ---------- Messages shell (new 2026-09-01) — built from Martin's\n     Messages.pdf rough wireframe: a \"+\" compose button and a filter\n     icon above a search bar, a scrollable thread list (each row an\n     avatar circle, the top one shown with a timestamp + sender name and\n     highlighted when unread), and a right-hand pane with a header block,\n     a right-aligned accent-colored sent bubble, and a rounded compose\n     pill at the bottom. Kept as a two-pane master/detail layout on\n     desktop; collapses to list-then-thread on narrow screens (see the\n     mobile media query) since the wireframe didn't specify mobile\n     behavior but every other page in this app supports it.\n     Per site-map.md/architecture-decisions.md: Messages is an opt-in\n     Social feature (off by default in Onboarding) and is meant to be\n     backed by the real Schoology Messages API (GET /v1/messages/inbox,\n     POST /v1/messages, etc.) — this static mock always shows the page\n     rather than checking that toggle (there's no persisted settings\n     state across these standalone pages yet), but a real build must\n     hide this nav item / block this route when the user hasn't opted\n     in. The compose recipient list below is deliberately sourced from\n     the same six teachers used elsewhere in the app's sample data\n     (/grades's COURSES) rather than any broader directory — that\n     mirrors the real API's GET /v1/messages/recipients, which is\n     Schoology's own server-computed \"who can I currently message\" list\n     already filtered by district policy (teacher-only vs. peer-to-peer),\n     per the decision logged 2026-08-24. ---------- */\n  /* Height-capped to whatever .page has left (flex: 1; min-height: 0)\n     instead of growing to match content -- keeps both panels' frames\n     (and their rounded corners) fixed on screen, matching login-style\n     app chrome. Also fixes a real bug this caused before being capped:\n     with the panel stretched taller than a short conversation's natural\n     content and nothing set to grow into the leftover space, that space\n     collected below .msgs-composer instead of the composer sitting\n     flush with the panel's bottom edge. Capping the shell and letting\n     .msgs-bubbles flex-grow (below) fixes both at once. max-height kept\n     so this doesn't balloon on a very tall monitor. */\n  .msgs-shell {\n    display: flex;\n    gap: 14px;\n    align-items: stretch;\n    flex: 1;\n    min-height: 0;\n    max-height: 660px;\n  }\n  .msgs-list-panel {\n    width: 320px;\n    flex-shrink: 0;\n    background: var(--panel-bg);\n    border-radius: var(--window-radius-lg);\n    display: flex;\n    flex-direction: column;\n    overflow: hidden;\n  }\n  .msgs-list-head {\n    display: flex;\n    align-items: center;\n    gap: 8px;\n    padding: 14px 14px 10px;\n    flex-shrink: 0;\n  }\n  .msgs-list-head[hidden] { display: none; }\n  .msgs-compose-btn {\n    width: 34px; height: 34px;\n    border-radius: 50%;\n    background: var(--accent);\n    color: #fff;\n    border: none;\n    cursor: pointer;\n    flex-shrink: 0;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n  }\n  .msgs-compose-btn svg { width: 16px; height: 16px; stroke: currentColor; fill: none; stroke-width: 2.4; stroke-linecap: round; }\n  .msgs-compose-btn:hover { background: var(--accent-dark); }\n  .msgs-compose-btn:focus-visible { outline: none; box-shadow: 0 0 0 2px var(--accent-ring); }\n  /* Search bar \"morph\": .msgs-search-wrap's own width is fixed by the\n     flex header row around it (flex:1) and never changes. What animates\n     is the split INSIDE it — the input is flex:1 so it fills whatever\n     space the clear button isn't using, and the clear button animates\n     its own width from 0 up to full size. The two transitions together\n     read as \"the search bar shrinks to make room for an X\", but the\n     bar's overall footprint in the header is constant throughout. */\n  .msgs-search-wrap { flex: 1; min-width: 0; display: flex; align-items: center; gap: 4px; }\n  #msgsSearch {\n    flex: 1 1 auto;\n    min-width: 0;\n    width: 100%;\n    border: none;\n    border-radius: 999px;\n    background: var(--panel-inner);\n    padding: 8px 14px;\n    font: inherit;\n    font-size: 0.82rem;\n    color: var(--text-dark);\n  }\n  #msgsSearch::placeholder { color: var(--text-faint); }\n  #msgsSearch:focus-visible { outline: none; box-shadow: 0 0 0 2px var(--accent-ring); }\n  .msgs-search-clear {\n    flex: 0 0 auto;\n    width: 0;\n    height: 32px;\n    padding: 0;\n    border: none;\n    background: none;\n    color: var(--text-faint);\n    cursor: pointer;\n    opacity: 0;\n    overflow: hidden;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    transition: width 0.22s ease, opacity 0.16s ease;\n  }\n  .msgs-search-clear.show { width: 30px; opacity: 1; }\n  .msgs-search-clear svg { width: 15px; height: 15px; stroke: currentColor; fill: none; stroke-width: 2.3; stroke-linecap: round; }\n  .msgs-search-clear:hover { color: var(--text-dark); }\n  .msgs-search-clear:focus-visible { outline: none; box-shadow: 0 0 0 2px var(--accent-ring); border-radius: 50%; }\n\n  /* Search results — replaces #threadList in the SAME slot (same\n     flex:1/overflow-y:auto box, see .msgs-thread-list) rather than\n     floating a dropdown over it, per Martin's request. Matches on message\n     BODY text (not\n     just conversation name/course), so a search for e.g. \"Unit 2\" can\n     surface a specific message buried in a thread; picking a row jumps\n     straight to that message (see jumpToMessage). */\n  .msgs-search-results { flex: 1; min-height: 0; overflow-y: auto; padding: 4px 10px 10px; }\n  .msgs-search-results[hidden] { display: none; }\n  /* Categorized results — Messages/Docs/Links/Video/Audio (2026-09-01):\n     the section headers always render, even for a category with zero\n     items, so the panel's shape stays stable as you type rather than\n     sections popping in/out. */\n  .msgs-search-scope { margin: 2px 4px 8px; padding: 7px 10px; background: var(--panel-inner); border-radius: var(--window-radius-sm); font-size: 0.78rem; font-weight: 600; color: var(--text-dark); }\n  .msgs-search-cat { padding: 2px 0 6px; }\n  .msgs-search-cat + .msgs-search-cat { border-top: 1px solid var(--border); }\n  .msgs-search-cat-title { margin: 8px 8px 2px; font-size: 0.66rem; font-weight: 800; text-transform: uppercase; letter-spacing: 0.03em; color: var(--text-faint); }\n  .msgs-search-cat-empty { margin: 0 8px 4px; font-size: 0.76rem; color: var(--text-faint); font-weight: 600; }\n  .msgs-file-chip {\n    width: 34px; height: 34px;\n    border-radius: 8px;\n    flex-shrink: 0;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    color: #fff;\n    font-size: 0.6rem;\n    font-weight: 900;\n    letter-spacing: 0.02em;\n  }\n  .msgs-media-chip {\n    width: 34px; height: 34px;\n    border-radius: 50%;\n    flex-shrink: 0;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    background: var(--panel-inner);\n    color: var(--text-muted);\n  }\n  .msgs-media-chip svg { width: 15px; height: 15px; stroke: currentColor; fill: none; stroke-width: 2.2; stroke-linecap: round; stroke-linejoin: round; }\n  .msgs-search-result-row {\n    display: flex;\n    align-items: center;\n    gap: 10px;\n    width: 100%;\n    background: none;\n    border: none;\n    border-radius: var(--window-radius-sm);\n    padding: 8px;\n    cursor: pointer;\n    text-align: left;\n    font: inherit;\n  }\n  .msgs-search-result-row:hover { background: var(--panel-inner); }\n  .msgs-search-result-row:focus-visible { outline: none; box-shadow: 0 0 0 2px var(--accent-ring) inset; }\n  .msgs-search-result-text { min-width: 0; flex: 1; }\n  /* display:block on both — as plain (inline-by-default) spans, the\n     white-space:nowrap/overflow:hidden/text-overflow:ellipsis below\n     didn't actually truncate anything: ellipsis truncation needs a\n     block (or inline-block) box, since a bare inline span has no width\n     of its own to clip against. Same fix already applied via <div> for\n     the thread-list row's name/subject/preview (see .msgs-thread-row-*\n     above) — this brings the search results panel in line with that so\n     a long message truncates with \"…\" here too instead of overflowing\n     or wrapping. */\n  .msgs-search-result-name { display: block; font-weight: 700; font-size: 0.8rem; color: var(--text-dark); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n  .msgs-search-result-snippet { display: block; font-size: 0.74rem; color: var(--text-muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; margin-top: 1px; }\n  .msgs-search-result-snippet mark { background: rgba(217,74,43,0.22); color: inherit; border-radius: 3px; padding: 0 1px; }\n  .msgs-filter-wrap { position: relative; flex-shrink: 0; }\n  .msgs-filter-btn {\n    width: 34px; height: 34px;\n    border-radius: 50%;\n    background: none;\n    border: none;\n    cursor: pointer;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    color: var(--text-muted);\n  }\n  .msgs-filter-btn:hover { background: var(--panel-inner); }\n  .msgs-filter-btn:focus-visible { outline: none; box-shadow: 0 0 0 2px var(--accent-ring); }\n  .msgs-filter-btn svg { width: 18px; height: 18px; stroke: currentColor; fill: none; stroke-width: 2.2; stroke-linecap: round; }\n  .msgs-filter-menu {\n    position: absolute;\n    top: calc(100% + 6px);\n    right: 0;\n    min-width: 120px;\n    background: var(--panel-bg);\n    border-radius: var(--window-radius-md);\n    box-shadow: 0 20px 45px -16px rgba(0,0,0,0.5);\n    padding: 6px;\n    z-index: 25;\n  }\n  .msgs-filter-item {\n    display: block;\n    width: 100%;\n    text-align: left;\n    background: none;\n    border: none;\n    border-radius: var(--window-radius-sm);\n    font: inherit;\n    font-weight: 700;\n    font-size: 0.82rem;\n    color: var(--text-dark);\n    padding: 8px 10px;\n    cursor: pointer;\n  }\n  .msgs-filter-item:hover { background: var(--panel-inner); }\n  .msgs-filter-item.active { color: var(--accent); }\n\n  /* Right-click context menu on a left-side thread row -- Pin/Unpin +\n     Delete (2026-09-04, per Martin). position:fixed and anchored to the\n     click coordinates in JS (see openRowContextMenu), not to a wrapper\n     element like .profile-menu/.msgs-filter-menu above, since it can\n     open from any row anywhere in the scrollable list. */\n  .msgs-row-context-menu {\n    position: fixed;\n    min-width: 150px;\n    background: var(--panel-bg);\n    border-radius: var(--window-radius-md);\n    box-shadow: 0 20px 45px -16px rgba(0,0,0,0.5);\n    padding: 6px;\n    z-index: 30;\n  }\n  .msgs-row-context-menu-item {\n    display: flex;\n    align-items: center;\n    gap: 9px;\n    width: 100%;\n    text-align: left;\n    background: none;\n    border: none;\n    border-radius: var(--window-radius-sm);\n    font: inherit;\n    font-weight: 700;\n    font-size: 0.86rem;\n    color: var(--text-dark);\n    padding: 9px 10px;\n    cursor: pointer;\n  }\n  .msgs-row-context-menu-item:hover { background: var(--panel-inner); }\n  .msgs-row-context-menu-item.delete { color: #b6432f; }\n  /* stroke: currentColor (not a hardcoded color) so the icon always\n     matches its button's text color, including the .delete variant above\n     -- avoids the kind of specificity/contrast bug the composer's link\n     styling hit earlier this project (see architecture-decisions.md). */\n  .msgs-row-context-menu-item svg { width: 15px; height: 15px; stroke: currentColor; fill: none; stroke-width: 2.1; stroke-linecap: round; stroke-linejoin: round; flex-shrink: 0; }\n\n  /* Scrolls on its own within the fixed-height panel -- .msgs-list-head\n     (the + / search / filter row above it) stays put. */\n  .msgs-thread-list { flex: 1; min-height: 0; overflow-y: auto; padding: 4px 10px 10px; }\n  .msgs-thread-row {\n    display: flex;\n    align-items: center;\n    gap: 10px;\n    padding: 10px 8px;\n    border-radius: var(--window-radius-md);\n    cursor: pointer;\n    margin-bottom: 2px;\n  }\n  .msgs-thread-row:hover { background: var(--panel-inner); }\n  .msgs-thread-row:focus-visible { outline: none; box-shadow: 0 0 0 2px var(--accent-ring) inset; }\n  .msgs-thread-row.active { background: var(--accent); }\n  .msgs-thread-row.active .msgs-thread-row-name,\n  .msgs-thread-row.active .msgs-thread-row-subject,\n  .msgs-thread-row.active .msgs-thread-row-preview,\n  .msgs-thread-row.active .msgs-thread-row-time { color: #fff; }\n  .msgs-thread-row.unread .msgs-thread-row-name { font-weight: 900; }\n  .msgs-thread-row.unread .msgs-thread-row-preview { color: var(--text-dark); font-weight: 600; }\n  .msgs-avatar {\n    width: 44px; height: 44px;\n    border-radius: 50%;\n    flex-shrink: 0;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    color: #fff;\n    font-weight: 800;\n    font-size: 1rem;\n    position: relative;\n    overflow: hidden;\n  }\n  .msgs-thread-row-text { min-width: 0; flex: 1; }\n  .msgs-thread-row-top { display: flex; align-items: baseline; justify-content: space-between; gap: 6px; }\n  .msgs-thread-row-name { font-weight: 700; font-size: 0.86rem; color: var(--text-dark); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n  /* Pin icon shown before a pinned conversation's name (2026-09-04, per\n     Martin). Lives inside .msgs-thread-row-name so it inherits that\n     span's color -- including the \"color: #fff\" override on .active\n     rows above -- automatically via currentColor, same reasoning as the\n     context-menu icons. */\n  .msgs-pin-icon { display: inline-flex; vertical-align: -2px; margin-right: 3px; }\n  .msgs-pin-icon svg { width: 11px; height: 11px; stroke: currentColor; fill: none; stroke-width: 2.4; stroke-linecap: round; stroke-linejoin: round; }\n  .msgs-thread-row-time { font-size: 0.66rem; font-weight: 700; color: var(--text-faint); flex-shrink: 0; }\n  /* Thread subject — distinguishes multiple separate threads with the\n     same person (2026-09-01), the same way an email subject line does. */\n  .msgs-thread-row-subject { font-size: 0.72rem; font-weight: 700; color: var(--text-muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; margin-top: 1px; }\n  .msgs-thread-row-preview { font-size: 0.76rem; color: var(--text-muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; margin-top: 1px; }\n  .msgs-unread-dot { width: 8px; height: 8px; border-radius: 50%; background: var(--accent); flex-shrink: 0; }\n  .msgs-thread-row.active .msgs-unread-dot { background: #fff; }\n  .msgs-empty-hint { font-size: 0.8rem; color: var(--text-faint); text-align: center; padding: 24px 12px; font-weight: 600; }\n\n  .msgs-thread-panel {\n    flex: 1;\n    min-width: 0;\n    background: #fdfdfe;\n    border-radius: var(--window-radius-lg);\n    display: flex;\n    flex-direction: column;\n    overflow: hidden;\n  }\n  .msgs-thread-empty {\n    flex: 1;\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    justify-content: center;\n    color: var(--text-faint);\n    font-weight: 700;\n    font-size: 0.9rem;\n    gap: 10px;\n    text-align: center;\n    padding: 20px;\n  }\n  .msgs-thread-empty svg { width: 42px; height: 42px; stroke: var(--text-faint); fill: none; stroke-width: 1.6; opacity: 0.55; }\n  .msgs-thread-empty p { margin: 0; max-width: 220px; line-height: 1.4; }\n  .msgs-thread-empty .hint { font-size: 0.76rem; font-weight: 600; opacity: 0.8; }\n\n  .msgs-thread-active { flex: 1; display: flex; flex-direction: column; min-height: 0; }\n  .msgs-thread-empty[hidden], .msgs-thread-active[hidden] { display: none; }\n  .msgs-thread-header {\n    display: flex;\n    align-items: center;\n    gap: 10px;\n    padding: 14px 18px;\n    border-bottom: 1px solid var(--border);\n    flex-shrink: 0;\n  }\n  .msgs-back-btn {\n    display: none;\n    background: none;\n    border: none;\n    color: var(--text-muted);\n    cursor: pointer;\n    padding: 0;\n    margin-right: 2px;\n    flex-shrink: 0;\n  }\n  .msgs-back-btn svg { width: 18px; height: 18px; stroke: currentColor; fill: none; stroke-width: 2.6; stroke-linecap: round; stroke-linejoin: round; }\n  .msgs-back-btn:focus-visible { outline: none; box-shadow: 0 0 0 2px var(--accent-ring); border-radius: 50%; }\n  .msgs-thread-avatar { width: 38px; height: 38px; border-radius: 50%; flex-shrink: 0; display: flex; align-items: center; justify-content: center; color: #fff; font-weight: 800; font-size: 0.88rem; position: relative; overflow: hidden; }\n  /* Wraps the avatar + name/course block so it can be swapped out as one\n     unit for .msgs-to-bar below when composing a brand-new message (see\n     the 2026-09-04 comment above .msgs-shell's redesign notes). */\n  .msgs-thread-identity { display: flex; align-items: center; gap: 10px; min-width: 0; flex: 1; }\n  .msgs-thread-identity[hidden] { display: none; }\n  .msgs-thread-head-text { min-width: 0; }\n  .msgs-thread-name { display: block; font-weight: 800; font-size: 0.94rem; color: var(--text-dark); }\n  .msgs-thread-course { display: block; font-size: 0.72rem; font-weight: 700; color: var(--text-faint); }\n\n  /* Subject dropdown under the person's name (2026-09-04, per Martin) --\n     click the subject + chevron to see every subject you've messaged\n     this person under, plus an \"All subjects\" option that merges them\n     into one timeline (see renderSubjectDropdown/showAllSubjectsFor). */\n  .msgs-thread-subject-row { position: relative; }\n  .msgs-thread-subject-row[hidden] { display: none; }\n  .msgs-thread-subject-trigger {\n    display: inline-flex;\n    align-items: center;\n    gap: 3px;\n    background: none;\n    border: none;\n    padding: 0;\n    margin: 0;\n    font: inherit;\n    font-size: 0.72rem;\n    font-weight: 700;\n    color: var(--text-faint);\n    cursor: pointer;\n    max-width: 100%;\n  }\n  .msgs-thread-subject-trigger:hover,\n  .msgs-thread-subject-trigger[aria-expanded=\"true\"] { color: var(--accent); }\n  .msgs-thread-subject-trigger:focus-visible { outline: none; box-shadow: 0 0 0 2px var(--accent-ring); border-radius: 4px; }\n  #threadSubjectTriggerLabel { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n  .msgs-thread-subject-chevron { width: 11px; height: 11px; stroke: currentColor; fill: none; stroke-width: 2.6; stroke-linecap: round; stroke-linejoin: round; flex-shrink: 0; transition: transform 0.15s ease; }\n  .msgs-thread-subject-trigger[aria-expanded=\"true\"] .msgs-thread-subject-chevron { transform: rotate(180deg); }\n  .msgs-thread-subject-menu {\n    position: absolute;\n    top: calc(100% + 6px);\n    left: 0;\n    min-width: 200px;\n    max-width: 280px;\n    background: var(--panel-bg);\n    border-radius: var(--window-radius-md);\n    box-shadow: 0 20px 45px -16px rgba(0,0,0,0.5);\n    padding: 6px;\n    z-index: 20;\n  }\n  .msgs-thread-subject-menu[hidden] { display: none; }\n  .msgs-thread-subject-menu-item {\n    display: block;\n    width: 100%;\n    text-align: left;\n    background: none;\n    border: none;\n    border-radius: var(--window-radius-sm);\n    font: inherit;\n    font-weight: 700;\n    font-size: 0.82rem;\n    color: var(--text-dark);\n    padding: 8px 10px;\n    cursor: pointer;\n    white-space: nowrap;\n    overflow: hidden;\n    text-overflow: ellipsis;\n  }\n  .msgs-thread-subject-menu-item:hover { background: var(--panel-inner); }\n  .msgs-thread-subject-menu-item.active { color: var(--accent); }\n  .msgs-thread-subject-menu-item.all-subjects { border-bottom: 1px solid var(--border); border-radius: var(--window-radius-sm) var(--window-radius-sm) 0 0; margin-bottom: 4px; padding-bottom: 10px; }\n\n  /* Divider pill between each person's threads in the merged \"All\n     subjects\" timeline (see renderMergedBubbles) -- named by subject so\n     it still reads clearly which conversation each group of messages\n     came from, even though they're no longer separated by thread. */\n  .msgs-subject-divider { display: flex; justify-content: center; margin: 14px 0 10px; }\n  .msgs-subject-divider:first-child { margin-top: 2px; }\n  .msgs-subject-divider span { font-size: 0.68rem; font-weight: 800; letter-spacing: 0.02em; text-transform: uppercase; color: var(--text-faint); background: var(--panel-inner); border-radius: 999px; padding: 4px 12px; }\n\n  /* Composer hint shown in place of a working composer while the merged\n     All Subjects view is open (see setComposerEnabled). */\n  .msgs-composer-hint { padding: 8px 18px 0; margin: 0; font-size: 0.74rem; font-weight: 700; color: var(--text-faint); text-align: center; }\n  .msgs-composer-hint[hidden] { display: none; }\n\n  /* ---------- New Message redesign (2026-09-04, per Martin) — replaces\n     the old separate \"swap the whole list panel to a people picker\"\n     compose flow. Existing conversations now stay visible in the list at\n     all times (\"the people that are alr there stay there\"); starting a\n     new message instead pins a \"New Message\" row at the top of that same\n     list (see the JS render logic) and, on the right, swaps the\n     avatar/name header (.msgs-thread-identity above) for this To bar --\n     a label plus a native <select> listing every person from the\n     Contacts directory (not just current teachers) -- and reveals a\n     required Subject field beneath it (Schoology requires a subject on\n     every new thread). The send box at the bottom is untouched. ---------- */\n  .msgs-to-bar { display: flex; align-items: center; gap: 8px; min-width: 0; flex: 1; }\n  .msgs-to-bar[hidden] { display: none; }\n  .msgs-to-label { font-size: 0.78rem; font-weight: 800; color: var(--text-muted); flex-shrink: 0; }\n  .msgs-to-search { position: relative; flex: 1; min-width: 0; }\n  .msgs-to-input {\n    width: 100%;\n    border: 1px solid var(--border);\n    border-radius: 10px;\n    padding: 7px 10px;\n    font: inherit;\n    font-size: 0.84rem;\n    color: var(--text-dark);\n    background: var(--panel-bg);\n  }\n  .msgs-to-input::placeholder { color: var(--text-faint); }\n  .msgs-to-input:focus-visible { outline: none; box-shadow: 0 0 0 2px var(--accent-ring); border-color: var(--accent); }\n  /* Results dropdown for the To search (2026-09-05) -- capped to\n     MAX_TO_RESULTS items in JS so this box has a fixed, predictable\n     height no matter how many people match or how big the district is. */\n  .msgs-to-results {\n    position: absolute;\n    top: calc(100% + 6px);\n    left: 0;\n    right: 0;\n    background: var(--panel-bg);\n    border-radius: var(--window-radius-md);\n    box-shadow: 0 20px 45px -16px rgba(0,0,0,0.5);\n    padding: 6px;\n    z-index: 20;\n    max-height: 280px;\n    overflow-y: auto;\n  }\n  .msgs-to-results[hidden] { display: none; }\n  .msgs-to-result-item {\n    display: flex;\n    align-items: baseline;\n    gap: 6px;\n    width: 100%;\n    text-align: left;\n    background: none;\n    border: none;\n    border-radius: var(--window-radius-sm);\n    font: inherit;\n    padding: 8px 10px;\n    cursor: pointer;\n  }\n  .msgs-to-result-item:hover,\n  .msgs-to-result-item.highlighted { background: var(--panel-inner); }\n  .msgs-to-result-name { font-weight: 700; font-size: 0.84rem; color: var(--text-dark); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n  .msgs-to-result-course { font-size: 0.72rem; font-weight: 600; color: var(--text-faint); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n  .msgs-to-no-results { padding: 8px 10px; font-size: 0.82rem; font-weight: 600; color: var(--text-faint); }\n  .msgs-subject-bar { padding: 10px 18px; border-bottom: 1px solid var(--border); flex-shrink: 0; }\n  .msgs-subject-bar[hidden] { display: none; }\n  .msgs-subject-input {\n    width: 100%;\n    border: 1px solid var(--border);\n    border-radius: 10px;\n    padding: 8px 12px;\n    font: inherit;\n    font-size: 0.84rem;\n    color: var(--text-dark);\n    background: var(--panel-bg);\n  }\n  .msgs-subject-input::placeholder { color: var(--text-faint); }\n  .msgs-subject-input:focus-visible { outline: none; box-shadow: 0 0 0 2px var(--accent-ring); border-color: var(--accent); }\n  /* The pinned \"New Message\" row's icon avatar -- a plain \"+\" instead of\n     a person's initial, since no recipient may be chosen yet. */\n  .msgs-avatar-new { background: var(--accent); }\n  .msgs-avatar-new svg { width: 18px; height: 18px; stroke: #fff; fill: none; stroke-width: 2.4; stroke-linecap: round; }\n\n  /* Scrolls on its own within the fixed-height panel -- .msgs-thread-header\n     (who you're texting) above and .msgs-composer (send box) below both\n     stay put. flex:1/min-height:0 is also what makes it consume any\n     leftover vertical space instead of that space collecting below the\n     composer -- see the .msgs-shell comment above. */\n  .msgs-bubbles { flex: 1; min-height: 0; overflow-y: auto; padding: 16px 18px; display: flex; flex-direction: column; gap: 10px; }\n  /* flex-direction:column so a message that also carries an attachment\n     (see .msgs-bubble-attachment) stacks the attachment chip right below\n     its bubble instead of side-by-side; a row with just a bubble looks\n     identical to before. */\n  .msgs-bubble-row { display: flex; flex-direction: column; gap: 6px; }\n  .msgs-bubble-row.me { align-items: flex-end; }\n  .msgs-bubble-row.them { align-items: flex-start; }\n  .msgs-bubble { max-width: 74%; padding: 9px 13px; border-radius: 16px; font-size: 0.84rem; line-height: 1.42; }\n  .msgs-bubble-row.them .msgs-bubble { background: var(--panel-inner); color: var(--text-dark); border-bottom-left-radius: 4px; }\n  .msgs-bubble-row.me .msgs-bubble { background: var(--accent); color: #fff; border-bottom-right-radius: 4px; }\n  .msgs-bubble-time { display: block; font-size: 0.62rem; font-weight: 700; margin-top: 4px; }\n  .msgs-bubble-row.them .msgs-bubble-time { color: var(--text-faint); }\n  .msgs-bubble-row.me .msgs-bubble-time { color: rgba(255,255,255,0.82); }\n  /* A file/link/video/audio genuinely shared IN this message — renders\n     right under it as its own small chip row, in the same panel style\n     regardless of who sent it (unlike the text bubble, which flips\n     color for \"me\"), matching how a real messaging app shows an\n     attachment distinctly from the text around it. */\n  .msgs-bubble-attachment { display: flex; align-items: center; gap: 9px; max-width: 74%; padding: 6px 12px 6px 6px; border-radius: 14px; background: var(--panel-inner); cursor: pointer; }\n  .msgs-bubble-attachment:hover { background: var(--border); }\n  .msgs-bubble-attachment .msgs-file-chip, .msgs-bubble-attachment .msgs-media-chip { width: 28px; height: 28px; font-size: 0.52rem; }\n  .msgs-bubble-attachment .msgs-media-chip svg { width: 13px; height: 13px; }\n  .msgs-bubble-attachment-text { min-width: 0; }\n  .msgs-bubble-attachment-name { display: block; max-width: 170px; font-size: 0.76rem; font-weight: 700; color: var(--text-dark); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n  /* Link attachments read as blue + underlined everywhere they appear\n     (2026-09-04, per Martin: \"make all other link attachments blue and\n     underlined\") -- both the pre-authored sample threads' links and any\n     newly auto-detected one (see extractLinkAttachment() further down)\n     render through the same renderBubbleAttachment(), which adds this\n     modifier class only when a.kind === 'link'. */\n  .msgs-bubble-attachment-name-link { color: var(--accent); text-decoration: underline; }\n  .msgs-bubble-attachment-meta { font-size: 0.66rem; font-weight: 600; color: var(--text-faint); }\n  .msgs-bubble-attachment-time { display: block; font-size: 0.62rem; font-weight: 700; color: var(--text-faint); margin-top: -2px; }\n  @keyframes msgsBubbleFlash {\n    0% { box-shadow: 0 0 0 0 rgba(217,74,43,0); }\n    25% { box-shadow: 0 0 0 4px rgba(217,74,43,0.6); }\n    100% { box-shadow: 0 0 0 0 rgba(217,74,43,0); }\n  }\n  .msgs-bubble-row.flash .msgs-bubble { animation: msgsBubbleFlash 1.4s ease; }\n\n  /* align-items:flex-end (not center) -- per Martin's 2026-09-04 request,\n     an attachment preview now lives INSIDE this box (see\n     .msgs-composer-box below) stacked above the text line, so the box\n     can grow taller than the attach/send buttons beside it. flex-end\n     keeps those buttons pinned to the bottom row instead of drifting to\n     the vertical middle of a taller box, matching where your thumb\n     expects Send to stay as the box grows. */\n  .msgs-composer { display: flex; align-items: flex-end; gap: 10px; padding: 12px 16px; border-top: 1px solid var(--border); flex-shrink: 0; }\n  /* The actual \"message box\" -- was just the bare <input> before; now a\n     bordered/rounded container so a pending attachment (see\n     .msgs-pending-attachment) can sit inside it, above the text line,\n     as one visually unified box that extends upward to fit both rather\n     than a separate chip floating above the whole composer row. With no\n     attachment it's a single row and the 20px radius on a ~40px-tall\n     box still reads as the original pill. */\n  .msgs-composer-box {\n    flex: 1;\n    min-width: 0;\n    display: flex;\n    flex-direction: column;\n    border: 1px solid var(--border);\n    border-radius: 20px;\n    background: var(--panel-bg);\n    overflow: hidden;\n  }\n  .msgs-composer-box:focus-within { box-shadow: 0 0 0 2px var(--accent-ring); border-color: var(--accent); }\n  /* Disabled while viewing the merged \"All subjects\" timeline (see\n     setComposerEnabled) -- there's no single thread to reply into. */\n  .msgs-composer-box:has(#composerInput:disabled) { background: var(--panel-inner); }\n  #composerInput {\n    border: none;\n    border-radius: 0;\n    padding: 10px 16px;\n    font: inherit;\n    font-size: 0.84rem;\n    color: var(--text-dark);\n    background: none;\n  }\n  #composerInput::placeholder { color: var(--text-faint); }\n  #composerInput:focus-visible { outline: none; }\n  #composerInput:disabled { color: var(--text-faint); cursor: not-allowed; }\n  .msgs-send-btn {\n    width: 38px; height: 38px;\n    border-radius: 50%;\n    background: var(--accent);\n    color: #fff;\n    border: none;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    cursor: pointer;\n    flex-shrink: 0;\n  }\n  .msgs-send-btn:hover { background: var(--accent-dark); }\n  .msgs-send-btn:focus-visible { outline: none; box-shadow: 0 0 0 2px var(--accent-ring); }\n  .msgs-send-btn svg { width: 16px; height: 16px; stroke: currentColor; fill: none; stroke-width: 2.2; stroke-linecap: round; stroke-linejoin: round; }\n  .msgs-send-btn:disabled { background: var(--text-faint); cursor: not-allowed; }\n  .msgs-attach-btn:disabled { cursor: not-allowed; opacity: 0.5; }\n  .msgs-attach-btn:disabled:hover { background: none; color: var(--text-muted); }\n  /* Sits between the input and the send button, per Martin's request. */\n  .msgs-attach-btn {\n    width: 36px; height: 36px;\n    border-radius: 50%;\n    background: none;\n    border: none;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    cursor: pointer;\n    flex-shrink: 0;\n    color: var(--text-muted);\n  }\n  .msgs-attach-btn:hover { background: var(--panel-inner); color: var(--text-dark); }\n  .msgs-attach-btn:focus-visible { outline: none; box-shadow: 0 0 0 2px var(--accent-ring); }\n  .msgs-attach-btn svg { width: 17px; height: 17px; stroke: currentColor; fill: none; stroke-width: 2.1; stroke-linecap: round; stroke-linejoin: round; }\n  /* Preview of files picked via the attach button, shown inside the\n     message box (.msgs-composer-box) above the text line until sent (or\n     removed individually). Lives inside the same bordered box as the\n     input rather than as its own separate bar floating above the whole\n     composer row; the box is fine extending upward to fit it.\n     2026-09-04 (per Martin, with a Claude-attachment-UI screenshot as\n     reference): now supports more than one pending attachment at once,\n     each shrunk into its own small square tile with an ×-remove button\n     sitting on its top-right corner, wrapping onto more rows as needed\n     rather than one long horizontal chip. Real document preview\n     (thumbnails) is explicitly out of scope per Martin (\"will come out\n     in later version\") — each tile is just the filename plus its\n     extension badge, same info the old single-chip version showed. */\n  .msgs-pending-attachment {\n    display: flex;\n    flex-wrap: wrap;\n    gap: 10px;\n    margin: 10px 10px 0;\n    flex-shrink: 0;\n  }\n  .msgs-pending-attachment[hidden] { display: none; }\n  .msgs-pending-attachment-tile {\n    position: relative;\n    width: 76px;\n    height: 76px;\n    border-radius: 14px;\n    background: var(--panel-inner);\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    justify-content: center;\n    gap: 6px;\n    padding: 8px 6px;\n    flex-shrink: 0;\n  }\n  .msgs-pending-attachment-tile-name {\n    font-size: 0.6rem;\n    font-weight: 700;\n    color: var(--text-dark);\n    text-align: center;\n    line-height: 1.2;\n    display: -webkit-box;\n    -webkit-line-clamp: 2;\n    -webkit-box-orient: vertical;\n    overflow: hidden;\n    word-break: break-word;\n  }\n  .msgs-pending-attachment-tile-ext {\n    font-size: 0.56rem;\n    font-weight: 900;\n    letter-spacing: 0.03em;\n    color: var(--text-muted);\n    background: var(--panel-bg);\n    padding: 2px 7px;\n    border-radius: 999px;\n  }\n  /* Sits on the tile's top-right corner (half overlapping, half clear\n     of it), matching the reference screenshot's remove-button style. */\n  .msgs-pending-attachment-tile-remove {\n    position: absolute;\n    top: -7px;\n    right: -7px;\n    width: 22px; height: 22px;\n    border-radius: 50%;\n    border: 2px solid var(--panel-bg);\n    background: var(--text-dark);\n    color: #fff;\n    cursor: pointer;\n    padding: 0;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    flex-shrink: 0;\n  }\n  .msgs-pending-attachment-tile-remove:hover { background: var(--accent-dark); }\n  .msgs-pending-attachment-tile-remove:focus-visible { outline: none; box-shadow: 0 0 0 2px var(--accent-ring); }\n  .msgs-pending-attachment-tile-remove svg { width: 11px; height: 11px; stroke: currentColor; fill: none; stroke-width: 2.6; stroke-linecap: round; }\n\n  /* Link detection while typing (2026-09-04, per Martin: \"when you type\n     a link, make it have the blue color and the underline\"). #composerInput\n     is a plain <input> (not contenteditable, to keep this simple and\n     robust rather than reimplementing caret handling), so this colors\n     the WHOLE typed line once it contains something URL-shaped, rather\n     than styling just the matched substring -- a reasonable stand-in for\n     a mock, and exactly matches the common case of a message that's\n     nothing but a pasted link. See the composerInput 'input' listener\n     (toggles this class) and URL_RE / extractLinkAttachment() further\n     down in the script. */\n  /* #composerInput (ID selector, higher specificity) also sets its own\n     color -- this needs the ID repeated here too, or that rule wins and\n     the text never visibly turns blue despite the class being applied. */\n  #composerInput.msgs-composer-link-active { color: var(--accent); text-decoration: underline; }\n\n  /* ---------- Bottom nav — copied verbatim ---------- */\n  .app-nav {\n    position: fixed;\n    left: 0;\n    right: 0;\n    bottom: 20px;\n    display: flex;\n    justify-content: center;\n    padding: 0 20px;\n    z-index: 10;\n    pointer-events: none;\n  }\n  .app-nav-inner {\n    display: flex;\n    gap: 4px;\n    width: 100%;\n    max-width: 940px;\n    overflow-x: auto;\n    scrollbar-width: none;\n    background: var(--panel-bg);\n    border-radius: var(--window-radius-md);\n    padding: 0 8px;\n    pointer-events: auto;\n  }\n  .app-nav-inner::-webkit-scrollbar { display: none; }\n  .nav-link {\n    background: none;\n    border: none;\n    cursor: pointer;\n    font-family: inherit;\n    flex: 1;\n    min-width: 0;\n    padding: 12px 6px 10px;\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    gap: 5px;\n  }\n  .nav-link .label { display: block; max-width: 100%; font-size: 0.72rem; font-weight: 800; color: var(--text-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; text-align: center; }\n  .nav-link:hover .label { color: var(--text-muted); }\n  .nav-link .dot { width: 4px; height: 4px; border-radius: 50%; background: transparent; }\n  .nav-link.active .label { color: var(--text-dark); }\n  .nav-link.active .dot { background: var(--accent); }\n  /* ---------- \"More\" overflow (2026-10-01, per Martin: \"if the text has\n     to get ... we should add a more button on the far right side with a\n     list of the other options\"). Labels never truncate: when they would,\n     the rightmost pages move into the More menu instead. ---------- */\n  .nav-link[hidden], .nav-more[hidden], .nav-more-menu[hidden] { display: none; }\n  /* While the More menu is open the whole bar sits above everything else on\n     the page (sticky headers, pop-ups, the edit button go up to z-index 90),\n     so the menu is never drawn underneath them. */\n  .app-nav.more-open { z-index: 1000; }\n  .nav-more {\n    background: none;\n    border: none;\n    cursor: pointer;\n    font-family: inherit;\n    flex: 0 0 auto;\n    position: relative;\n    margin-left: 4px;\n    padding: 12px 16px 10px;\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    gap: 5px;\n  }\n  .nav-more .label { display: flex; align-items: center; height: 1.2em; font-size: 0.72rem; color: var(--text-faint); }\n  .nav-more .label svg { display: block; fill: currentColor; }\n  /* thin divider between the pages and the dots */\n  .nav-more::before { content: \"\"; position: absolute; left: 0; top: 12px; bottom: 12px; width: 1px; background: var(--border, #cfcfd6); }\n  .nav-more:hover .label, .nav-more[aria-expanded=\"true\"] .label { color: var(--text-dark); }\n  .nav-more .dot { width: 4px; height: 4px; border-radius: 50%; background: transparent; }\n  .nav-more.has-active .label { color: var(--text-dark); }\n  .nav-more.has-active .dot { background: var(--accent); }\n  .nav-more:focus-visible { outline: none; box-shadow: 0 0 0 3px var(--accent-ring) inset; }\n  .nav-more-menu {\n    position: absolute;\n    bottom: calc(100% + 8px);\n    right: 20px;\n    min-width: 168px;\n    padding: 8px;\n    display: flex;\n    flex-direction: column;\n    gap: 4px;\n    background: var(--panel-bg);\n    border-radius: var(--window-radius-md);\n    box-shadow: 0 12px 32px rgba(0, 0, 0, 0.18);\n    pointer-events: auto;\n  }\n  .nav-more-item {\n    background: none;\n    border: none;\n    cursor: pointer;\n    font-family: inherit;\n    font-size: 0.8rem;\n    font-weight: 800;\n    color: var(--text-faint);\n    text-align: left;\n    padding: 12px 12px;\n    border-radius: 8px;\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    gap: 12px;\n  }\n  .nav-more-item:hover, .nav-more-item:focus-visible { outline: none; color: var(--text-dark); box-shadow: 0 0 0 3px var(--accent-ring) inset; }\n  .nav-more-item.active { color: var(--text-dark); }\n  .nav-more-item.active span { position: relative; display: inline-block; padding-bottom: 6px; margin-bottom: -6px; }\n  .nav-more-item.active span::after { content: \"\"; position: absolute; left: 0; right: 0; bottom: 0; height: 3px; border-radius: 999px; background: var(--accent); }\n  /* Labels sit centered in the bar; the active page is underlined in the\n     accent color instead of marked with a dot (2026-10-01, per Martin). */\n  .app-nav-inner .nav-link, .app-nav-inner .nav-more { justify-content: center; gap: 0; padding-top: 10px; padding-bottom: 10px; }\n  .app-nav-inner .nav-link .dot, .app-nav-inner .nav-more .dot { display: none; }\n  .app-nav-inner .nav-link .label, .app-nav-inner .nav-more .label { position: relative; padding: 6px 0; }\n  .app-nav-inner .nav-link.active .label::after, .app-nav-inner .nav-more.has-active .label::after { content: \"\"; position: absolute; left: 0; right: 0; bottom: 0; height: 3px; border-radius: 999px; background: var(--accent); }\n  @media (max-width: 520px) {\n    .nav-more { padding: 10px 12px 8px; }\n    .nav-more::before { top: 10px; bottom: 10px; }\n    .app-nav-inner .nav-link, .app-nav-inner .nav-more { padding-top: 8px; padding-bottom: 8px; }\n    .nav-more .label { font-size: 0.58rem; }\n  }\n  .nav-link:focus-visible { outline: none; box-shadow: 0 0 0 3px var(--accent-ring) inset; }\n\n  @media (max-width: 720px) {\n    .msgs-list-panel { width: 100%; }\n    .msgs-shell:not(.thread-open) .msgs-thread-panel { display: none; }\n    .msgs-shell.thread-open .msgs-list-panel { display: none; }\n    .msgs-shell.thread-open .msgs-thread-panel { display: flex; }\n    .msgs-back-btn { display: inline-flex; align-items: center; }\n  }\n  @media (max-width: 520px) {\n    .nav-link { min-width: 0; padding: 10px 3px 8px; }\n    .nav-link .label { font-size: 0.58rem; }\n  }\n\n  /* ---------- Contact info popup (2026-09-08) — same .modal-overlay/\n     .modal-box/.contact-modal-* convention as /contacts's own contact\n     detail modal, copied verbatim so the two look and behave identically. ---------- */\n  .modal-overlay {\n    position: fixed;\n    inset: 0;\n    background: rgba(20, 21, 31, 0.45);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    padding: 20px;\n    opacity: 0;\n    visibility: hidden;\n    transition: opacity 0.16s ease;\n    z-index: 60;\n  }\n  .modal-overlay.show { opacity: 1; visibility: visible; }\n  .modal-box {\n    background: var(--panel-bg, #eaeaec);\n    border-radius: var(--window-radius-lg, 22px);\n    padding: 20px 22px;\n    width: 100%;\n    max-width: 340px;\n    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);\n    position: relative;\n    transform: translateY(8px);\n    transition: transform 0.16s ease;\n  }\n  .modal-overlay.show .modal-box { transform: translateY(0); }\n  .modal-close {\n    position: absolute;\n    top: 12px;\n    right: 12px;\n    background: none;\n    border: none;\n    font-size: 1rem;\n    color: var(--text-faint);\n    cursor: pointer;\n    padding: 4px;\n    line-height: 1;\n  }\n  .modal-close:hover { color: var(--text-dark); }\n  .contact-modal-head { display: flex; align-items: center; gap: 12px; clear: both; padding-top: 4px; }\n  .contact-modal-avatar {\n    width: 48px;\n    height: 48px;\n    border-radius: 50%;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    color: #fff;\n    font-weight: 800;\n    font-size: 1.05rem;\n    flex-shrink: 0;\n  }\n  .modal-box h3 { margin: 0; font-size: 1.1rem; font-weight: 900; font-style: italic; color: var(--text-dark); }\n  .modal-code { font-size: 0.78rem; font-weight: 700; color: var(--text-muted); margin: 2px 0 0; }\n  .modal-row { display: flex; justify-content: space-between; gap: 10px; padding: 7px 0; border-bottom: 1px solid var(--border); font-size: 0.8rem; }\n  .modal-row:last-of-type { border-bottom: none; }\n  .modal-row .k { color: var(--text-faint); font-weight: 700; }\n  .modal-row .v { color: var(--text-dark); font-weight: 700; text-align: right; }\n  .modal-rows { margin-top: 14px; }\n  .contact-modal-actions { display: flex; gap: 8px; margin-top: 16px; }\n  .contact-modal-btn {\n    flex: 1;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    gap: 6px;\n    padding: 9px 10px;\n    border-radius: 999px;\n    border: none;\n    background: var(--accent);\n    color: #fff;\n    font-weight: 800;\n    font-size: 0.78rem;\n    cursor: pointer;\n    text-decoration: none;\n  }\n  .contact-modal-btn:hover { background: var(--accent-dark); }\n  .contact-modal-btn:focus-visible { outline: none; box-shadow: 0 0 0 2px var(--accent-ring); }\n  .contact-modal-btn svg { width: 15px; height: 15px; stroke: currentColor; fill: none; stroke-width: 2.3; stroke-linecap: round; stroke-linejoin: round; }\n  .contact-modal-btn.secondary { background: var(--panel-inner); color: var(--text-dark); }\n  .contact-modal-btn.secondary:hover { background: var(--border); }\n  /* The To box's selected-recipient state (see selectToPerson) — visually\n     signals it's now clickable-for-info rather than free-typed text. */\n  .msgs-to-input.msgs-to-selected { cursor: pointer; }\n  /* Emoji icons (2026-10-01, per Martin): icons that show a thing are emoji;\n     buttons and action icons stay line icons. */\n  /* Each emoji is an inline SVG sized by font-size (1em box), so it is\n     exactly as big as its box and sits dead center. The svg rule undoes\n     the line-icon styles (stroke, fill:none, opacity) that the parent\n     rows still set for their other icons. */\n  .emo { display: inline-block; width: 1em; height: 1em; line-height: 0; flex-shrink: 0; vertical-align: middle; }\n  .emo svg { display: block; width: 100%; height: 100%; fill: initial; stroke: none; opacity: 1; }\n  .msgs-media-chip .emo { font-size: 16px; }\n  .msgs-bubble-attachment .msgs-media-chip .emo { font-size: 14px; }\n  .msgs-pin-icon .emo { font-size: 11px; }\n  .msgs-thread-empty .emo { font-size: 40px; margin-bottom: 4px; }\n\n  /* ---------- Signed in: real Schoology messages (2026-10-06) ---------- */\n  /* Inbox states in the list: loading, couldn't load (Try again), empty. */\n  .msgs-list-state { padding: 32px 16px; text-align: center; color: var(--text-faint); font-size: 0.8rem; font-weight: 600; line-height: 1.45; }\n  .msgs-list-state p { margin: 0 0 8px; }\n  .msgs-list-state .msgs-list-state-title { color: var(--text-dark); font-weight: 800; font-size: 0.88rem; }\n  .msgs-list-state .msgs-state-btn { margin-top: 4px; }\n  /* A thread that couldn't load, in the bubbles area. */\n  .msgs-thread-state { display: flex; flex-direction: column; align-items: center; gap: 8px; padding: 24px 12px; }\n  .msgs-thread-state .msgs-empty-hint { padding: 0; }\n  .msgs-thread-state.compact { padding: 8px 12px; }\n  .msgs-state-btn { display: inline-block; border: none; border-radius: 999px; background: var(--accent); color: #fff; font: inherit; font-weight: 800; font-size: 0.8rem; padding: 8px 16px; cursor: pointer; text-decoration: none; }\n  .msgs-state-btn:hover { background: var(--accent-dark); }\n  .msgs-state-btn:focus-visible { outline: none; box-shadow: 0 0 0 2px var(--accent-ring); }\n  /* A message that didn't go through: says so under the bubble, with Retry. */\n  .msgs-bubble-failed { display: flex; align-items: center; justify-content: flex-end; gap: 8px; max-width: 80%; text-align: right; font-size: 0.7rem; font-weight: 700; color: #b6432f; }\n  .msgs-subject-input[aria-invalid=\"true\"] { border-color: #b6432f; }\n  .msgs-retry-btn { border: none; border-radius: 999px; background: var(--panel-inner); color: var(--text-dark); font: inherit; font-weight: 800; font-size: 0.7rem; padding: 4px 12px; cursor: pointer; }\n  .msgs-retry-btn:hover { background: var(--border); }\n  .msgs-retry-btn:focus-visible { outline: none; box-shadow: 0 0 0 2px var(--accent-ring); }\n  /* Group threads: who wrote each incoming message. */\n  .msgs-bubble-author { font-size: 0.66rem; font-weight: 800; color: var(--text-faint); margin: 0 0 -2px 4px; }\n  /* Real messages keep their line breaks, and a long link wraps instead of\n     stretching the bubble past the panel. */\n  .msgs-shell.live .msgs-bubble { white-space: pre-wrap; overflow-wrap: anywhere; }\n  .msgs-row-context-menu-item[hidden], .modal-row[hidden] { display: none; }\n  /* Google Classroom has no messages: one panel with a note, no list and\n     no composer. After the 720px rule above on purpose, so this wins on\n     phones too. */\n  .msgs-shell.no-messaging .msgs-list-panel { display: none; }\n  .msgs-shell.no-messaging .msgs-thread-panel { display: flex; }\n  .msgs-shell.no-messaging .msgs-thread-empty p { max-width: 340px; }\n  .msgs-shell.no-messaging .msgs-thread-empty .msgs-no-messaging-title { color: var(--text-dark); }\n  .msgs-shell.no-messaging .msgs-thread-empty .msgs-state-btn { margin-top: 4px; }\n";
const BODY_HTML = "\n  <div class=\"page\">\n    <div class=\"topbar\">\n      <div>\n        <h1 class=\"title\">Messages</h1>\n        <p class=\"subtitle\" id=\"msgsSubtitle\"></p>\n      </div>\n      <div class=\"profile-menu-wrap\">\n        <button class=\"profile-btn\" id=\"profileBtn\" type=\"button\" aria-haspopup=\"menu\" aria-expanded=\"false\" aria-label=\"Profile and settings\">M</button>\n        <div class=\"profile-menu\" id=\"profileMenu\" role=\"menu\" hidden>\n          <button class=\"profile-menu-item\" type=\"button\" role=\"menuitem\" data-action=\"settings\">Settings</button>\n          <button class=\"profile-menu-item signout\" type=\"button\" role=\"menuitem\" data-action=\"signout\">Sign out</button>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"msgs-shell\" id=\"msgsShell\">\n      <div class=\"msgs-list-panel\">\n        <div class=\"msgs-list-head\" id=\"listHeadDefault\">\n          <button class=\"msgs-compose-btn\" id=\"composeBtn\" type=\"button\" aria-label=\"New message\">\n            <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M12 5v14M5 12h14\"/></svg>\n          </button>\n          <div class=\"msgs-search-wrap\" id=\"searchWrap\">\n            <input type=\"search\" id=\"msgsSearch\" placeholder=\"Search\" aria-label=\"Search messages\" autocomplete=\"off\">\n            <button class=\"msgs-search-clear\" id=\"searchClearBtn\" type=\"button\" aria-label=\"Clear search\">\n              <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M6 6l12 12M18 6L6 18\"/></svg>\n            </button>\n          </div>\n          <div class=\"msgs-filter-wrap\">\n            <button class=\"msgs-filter-btn\" id=\"filterBtn\" type=\"button\" aria-haspopup=\"menu\" aria-expanded=\"false\" aria-label=\"Filter messages\">\n              <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><line x1=\"4\" y1=\"7\" x2=\"20\" y2=\"7\"/><line x1=\"7\" y1=\"12\" x2=\"17\" y2=\"12\"/><line x1=\"10\" y1=\"17\" x2=\"14\" y2=\"17\"/></svg>\n            </button>\n            <div class=\"msgs-filter-menu\" id=\"filterMenu\" role=\"menu\" hidden>\n              <button class=\"msgs-filter-item active\" type=\"button\" role=\"menuitem\" data-filter=\"all\">All</button>\n              <button class=\"msgs-filter-item\" type=\"button\" role=\"menuitem\" data-filter=\"unread\">Unread</button>\n              <!-- 2026-09-05, per Martin -- combines every person's separate\n                   subject threads into one row each, reusing the \"All\n                   subjects\" merged view already built for the per-person\n                   subject dropdown (see showAllSubjectsFor/renderMergedBubbles\n                   above). A standalone filter choice, not a modifier on\n                   All/Unread -- see combinedRows()/combinedRowHtml() below. -->\n              <button class=\"msgs-filter-item\" type=\"button\" role=\"menuitem\" data-filter=\"combined\">Combined</button>\n            </div>\n          </div>\n        </div>\n        <div class=\"msgs-thread-list\" id=\"threadList\"></div>\n        <div class=\"msgs-search-results\" id=\"searchResults\" hidden></div>\n      </div>\n\n      <!-- Right-click menu for a left-side thread row (2026-09-04, per\n           Martin) -- Pin/Unpin + Delete. Never opens for the pinned \"New\n           Message\" draft row (see the contextmenu listener on threadList\n           further down). -->\n      <div class=\"msgs-row-context-menu\" id=\"rowContextMenu\" role=\"menu\" hidden>\n        <button class=\"msgs-row-context-menu-item\" type=\"button\" role=\"menuitem\" id=\"rowContextPinBtn\">\n          <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0 1 18 0z\"/><circle cx=\"12\" cy=\"10\" r=\"3\"/></svg>\n          <span id=\"rowContextPinLabel\">Pin</span>\n        </button>\n        <button class=\"msgs-row-context-menu-item delete\" type=\"button\" role=\"menuitem\" id=\"rowContextDeleteBtn\">\n          <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M3 6h18M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2m3 0v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6h14z\"/><path d=\"M10 11v6M14 11v6\"/></svg>\n          Delete\n        </button>\n      </div>\n\n      <div class=\"msgs-thread-panel\">\n        <div class=\"msgs-thread-empty\" id=\"threadEmpty\">\n          <span class=\"emo\" aria-hidden=\"true\"><svg aria-hidden=\"true\" focusable=\"false\" viewBox=\"0 0 36 36\"><path fill=\"#BDDDF4\" d=\"M18 1C8.059 1 0 7.268 0 15c0 4.368 2.574 8.268 6.604 10.835C6.08 28.144 4.859 31.569 2 35c5.758-.96 9.439-3.761 11.716-6.416 1.376.262 2.805.416 4.284.416 9.941 0 18-6.268 18-14S27.941 1 18 1z\"/><circle cx=\"18\" cy=\"15\" r=\"2\" fill=\"#2A6797\"/><circle cx=\"26\" cy=\"15\" r=\"2\" fill=\"#2A6797\"/><circle cx=\"10\" cy=\"15\" r=\"2\" fill=\"#2A6797\"/></svg></span>\n          <p>Select a conversation</p>\n        </div>\n        <div class=\"msgs-thread-active\" id=\"threadActive\" hidden>\n          <div class=\"msgs-thread-header\">\n            <button class=\"msgs-back-btn\" id=\"threadBackBtn\" type=\"button\" aria-label=\"Back to messages\">\n              <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M15 18l-6-6 6-6\"/></svg>\n            </button>\n            <div class=\"msgs-thread-identity\" id=\"threadIdentity\">\n              <span class=\"msgs-thread-avatar\" id=\"threadAvatar\"></span>\n              <div class=\"msgs-thread-head-text\">\n                <span class=\"msgs-thread-name\" id=\"threadName\"></span>\n                <span class=\"msgs-thread-course\" id=\"threadCourse\"></span>\n                <!-- Subject dropdown (2026-09-04, per Martin: \"a down\n                     arrow on the subject... a dropdown with every\n                     subject you messaged under and at the top an all\n                     subjects option\"). Shown only for a real opened\n                     thread or the merged All Subjects view (see\n                     renderSubjectDropdown/showThread/showAllSubjectsFor)\n                     -- stays hidden during the New Message compose flows,\n                     which use #subjectBar's text input instead since\n                     there's no existing subject to pick from yet. -->\n                <div class=\"msgs-thread-subject-row\" id=\"threadSubjectRow\" hidden>\n                  <button type=\"button\" class=\"msgs-thread-subject-trigger\" id=\"threadSubjectTrigger\" aria-haspopup=\"menu\" aria-expanded=\"false\">\n                    <span id=\"threadSubjectTriggerLabel\"></span>\n                    <svg class=\"msgs-thread-subject-chevron\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M6 9l6 6 6-6\"/></svg>\n                  </button>\n                  <div class=\"msgs-thread-subject-menu\" id=\"threadSubjectMenu\" role=\"menu\" hidden></div>\n                </div>\n              </div>\n            </div>\n            <div class=\"msgs-to-bar\" id=\"toBar\" hidden>\n              <label class=\"msgs-to-label\" for=\"toInput\">To</label>\n              <!-- Search-as-you-type recipient picker (2026-09-05, per\n                   Martin: a plain list of every person in the district\n                   doesn't scale -- a real district can have hundreds of\n                   people, so this needs to filter down as you type rather\n                   than dump the whole directory in a dropdown). See\n                   renderToResults()/directoryMatches() below: results are\n                   capped at MAX_TO_RESULTS so the list can never overflow\n                   the page regardless of district size. -->\n              <div class=\"msgs-to-search\" id=\"toSearchWrap\">\n                <input type=\"text\" id=\"toInput\" class=\"msgs-to-input\" placeholder=\"Type a name…\" aria-label=\"Search for a person to message\" autocomplete=\"off\" role=\"combobox\" aria-expanded=\"false\" aria-haspopup=\"listbox\" aria-controls=\"toResults\">\n                <div class=\"msgs-to-results\" id=\"toResults\" role=\"listbox\" hidden></div>\n              </div>\n            </div>\n          </div>\n          <div class=\"msgs-subject-bar\" id=\"subjectBar\" hidden>\n            <input type=\"text\" id=\"subjectInput\" class=\"msgs-subject-input\" placeholder=\"Subject\" aria-label=\"Subject\">\n          </div>\n          <div class=\"msgs-bubbles\" id=\"threadBubbles\"></div>\n          <!-- Plain div, not a <form> (changed 2026-09-04, per Martin's\n               report that sending didn't work for him): this page gets\n               opened inside a sandboxed preview iframe in some surfaces,\n               and a sandboxed iframe without the \"allow-forms\" permission\n               silently blocks real <form> submission at the browser\n               level -- before our JS even runs, so e.preventDefault()\n               never gets the chance to matter. Send now happens off a\n               plain button click + a keydown listener on the input (see\n               sendComposerMessage() in the script), which isn't form\n               submission at all and isn't affected by that restriction. -->\n          <!-- Shown instead of letting the composer just silently do\n               nothing while viewing the merged \"All subjects\" timeline\n               (2026-09-04, per Martin's subject-dropdown request) -- there's\n               no single thread to append a reply to, so the composer is\n               disabled (see setComposerEnabled) until a specific subject is\n               chosen from the dropdown above. -->\n          <p class=\"msgs-composer-hint\" id=\"composerHint\" hidden>Select a specific subject above to reply.</p>\n          <!-- Signed in (2026-10-06): short notes such as \"Attachments aren't\n               supported yet\" (see showComposerNote). -->\n          <p class=\"msgs-composer-hint\" id=\"composerNote\" role=\"status\" hidden></p>\n          <div class=\"msgs-composer\" id=\"composerForm\">\n            <div class=\"msgs-composer-box\" id=\"composerBox\">\n              <div class=\"msgs-pending-attachment\" id=\"pendingAttachmentBar\" hidden></div>\n              <input type=\"text\" id=\"composerInput\" placeholder=\"Type a message…\" autocomplete=\"off\" aria-label=\"Type a message\">\n            </div>\n            <input type=\"file\" id=\"attachFileInput\" multiple hidden>\n            <button type=\"button\" class=\"msgs-attach-btn\" id=\"attachBtn\" aria-label=\"Add attachment\">\n              <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M21.44 11.05l-9.19 9.19a5 5 0 0 1-7.07-7.07l9.19-9.19a3.5 3.5 0 0 1 4.95 4.95l-9.2 9.19a2 2 0 0 1-2.83-2.83l8.49-8.48\"/></svg>\n            </button>\n            <button type=\"button\" class=\"msgs-send-btn\" id=\"sendBtn\" aria-label=\"Send message\">\n              <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M22 2 11 13\"/><path d=\"M22 2 15 22l-4-9-9-4Z\"/></svg>\n            </button>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Contact info popup (2026-09-08, fixing Martin's report: \"clicking on\n       people's name inside of the type a message box at the top won't open\n       their contact info popup\" — before this fix, a selected recipient's\n       name just sat as plain text inside the To <input>, which can never be\n       \"clicked\" as a name — clicking an input only places a text cursor.\n       Same .modal-overlay/.modal-box convention as /contacts's own\n       contact detail modal (deliberately trimmed here: no Message button,\n       since you're already composing to this person — just a link out to\n       the fuller /contacts record). -->\n  <div class=\"modal-overlay\" id=\"toContactModal\">\n    <div class=\"modal-box\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"toContactModalName\">\n      <button class=\"modal-close\" id=\"toContactModalCloseBtn\" type=\"button\" aria-label=\"Close contact info\">✕</button>\n      <div class=\"contact-modal-head\">\n        <span class=\"contact-modal-avatar\" id=\"toContactModalAvatar\"></span>\n        <div>\n          <h3 id=\"toContactModalName\"></h3>\n          <p class=\"modal-code\" id=\"toContactModalRole\"></p>\n        </div>\n      </div>\n      <div class=\"modal-rows\">\n        <div class=\"modal-row\"><span class=\"k\">Department</span><span class=\"v\" id=\"toContactModalDept\"></span></div>\n      </div>\n      <div class=\"contact-modal-actions\">\n        <a class=\"contact-modal-btn secondary\" id=\"toContactModalViewBtn\" href=\"#\">\n          <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"8\" r=\"4\"/><path d=\"M4 21c0-4.4 3.6-8 8-8s8 3.6 8 8\"/></svg>\n          View full contact\n        </a>\n      </div>\n    </div>\n  </div>\n\n  <nav class=\"app-nav\" aria-label=\"Main navigation\">\n    <div class=\"app-nav-inner\">\n      <button class=\"nav-link\" type=\"button\" data-page=\"home\" data-href=\"/home\">\n        <span class=\"label\">Home</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"courses\" data-href=\"/courses\">\n        <span class=\"label\">Courses</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"grades\" data-href=\"/grades\">\n        <span class=\"label\">Grades</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"assignments\" data-href=\"/assignments\">\n        <span class=\"label\">Assignments</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"files\" data-href=\"/files\">\n        <span class=\"label\">Files</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"calendar\" data-href=\"/calendar\">\n        <span class=\"label\">Calendar</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link active\" type=\"button\" data-page=\"messages\">\n        <span class=\"label\">Messages</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"contacts\" data-href=\"/contacts\">\n        <span class=\"label\">Contacts</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"settings\" data-href=\"/settings\">\n        <span class=\"label\">Settings</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-more\" type=\"button\" id=\"navMore\" aria-haspopup=\"menu\" aria-expanded=\"false\" aria-controls=\"navMoreMenu\" aria-label=\"More pages\" hidden>\n        <span class=\"label\"><svg viewBox=\"0 0 16 4\" width=\"16\" height=\"4\" aria-hidden=\"true\"><circle cx=\"2\" cy=\"2\" r=\"1.75\"/><circle cx=\"8\" cy=\"2\" r=\"1.75\"/><circle cx=\"14\" cy=\"2\" r=\"1.75\"/></svg></span>\n        <span class=\"dot\"></span>\n      </button>\n    </div>\n    <div class=\"nav-more-menu\" id=\"navMoreMenu\" role=\"menu\" aria-label=\"More pages\" hidden></div>\n  </nav>\n\n  \n\n\n  \n  \n";
const SCRIPT_JS = "\n    // Potato PC Mode on every page (2026-10-04, per Martin). The saved\n    // setting turns off all CSS animations and transitions, makes animate()\n    // calls and smooth scrolling instant, and drops the slanted page title.\n    // Same code as app/lib/theme-boot.ts, which runs it before first paint in\n    // the app; this copy covers the preview and pages theme-boot skips.\n    (function () {\n    var POTATO_CSS = \"body.potato-mode,body.potato-mode *,body.potato-mode *::before,body.potato-mode *::after{animation:none!important;transition:none!important;scroll-behavior:auto!important;filter:none!important;text-shadow:none!important}html:has(body.potato-mode){scroll-behavior:auto!important}body.potato-mode,body.potato-mode *{font-family:system-ui,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif!important}body.potato-mode h1.title{font-style:normal!important;transform:none!important}body.potato-mode .trend.has-popup:focus-visible{outline:2px solid currentColor;outline-offset:2px}\";\n    function potatoOn() { return !!(document.body && document.body.classList.contains(\"potato-mode\")); }\n    function applyPotato() {\n      var on = false;\n      try { on = (JSON.parse(localStorage.getItem(\"schoolagy_settings_options\") || \"{}\") || {}).potatoMode === true; } catch (e) {}\n      if (document.body) document.body.classList.toggle(\"potato-mode\", on);\n      if (!document.getElementById(\"potatoStyle\")) {\n        var st = document.createElement(\"style\");\n        st.id = \"potatoStyle\";\n        st.textContent = POTATO_CSS;\n        (document.head || document.documentElement).appendChild(st);\n      }\n      var EP = window.Element && Element.prototype;\n      if (EP && !EP.__potatoPatched) {\n        EP.__potatoPatched = true;\n        var anim = EP.animate;\n        if (anim) EP.animate = function (frames, opts) {\n          if (potatoOn()) opts = (typeof opts === \"number\" || opts == null) ? { duration: 0 } : Object.assign({}, opts, { duration: 0, delay: 0, endDelay: 0, iterations: 1 });\n          return anim.call(this, frames, opts);\n        };\n        var siv = EP.scrollIntoView;\n        if (siv) EP.scrollIntoView = function (arg) {\n          if (potatoOn() && arg && typeof arg === \"object\") arg = Object.assign({}, arg, { behavior: \"auto\" });\n          return siv.call(this, arg);\n        };\n        [\"scrollTo\", \"scrollBy\"].forEach(function (name) {\n          [EP, window].forEach(function (target) {\n            var fn = target[name];\n            if (!fn) return;\n            target[name] = function (a, b) {\n              if (potatoOn() && a && typeof a === \"object\") a = Object.assign({}, a, { behavior: \"auto\" });\n              return b === undefined ? fn.call(this, a) : fn.call(this, a, b);\n            };\n          });\n        });\n      }\n    }\n      applyPotato();\n      window.addEventListener('storage', function (e) { if (e.key === 'schoolagy_settings_options') applyPotato(); });\n    })();\n\n    // Bottom nav \"More\" overflow. Shows as many pages as fit without\n    // cutting a label off (\"Cour...\"); the rest go in the More menu.\n    // The current page always stays in the bar.\n    (function () {\n      const nav = document.querySelector('.app-nav');\n      const inner = nav && nav.querySelector('.app-nav-inner');\n      const more = document.getElementById('navMore');\n      const menu = document.getElementById('navMoreMenu');\n      if (!inner || !more || !menu) return;\n      const links = Array.from(inner.querySelectorAll('.nav-link'));\n\n      const cut = () =>\n        inner.scrollWidth > inner.clientWidth + 1 ||\n        links.some(l => !l.hidden && l.querySelector('.label').scrollWidth > l.querySelector('.label').clientWidth + 1);\n\n      function fit() {\n        closeMenu();\n        links.forEach(l => { l.hidden = false; });\n        more.hidden = true;\n        if (!cut()) return;\n        more.hidden = false;\n        // Hide from the right, but never the current page.\n        for (let i = links.length - 1; i >= 1 && cut(); i--) {\n          if (!links[i].classList.contains('active')) links[i].hidden = true;\n        }\n        const hidden = links.filter(l => l.hidden);\n        more.classList.toggle('has-active', hidden.some(l => l.classList.contains('active')));\n        menu.textContent = '';\n        hidden.forEach(l => {\n          const item = document.createElement('button');\n          item.type = 'button';\n          item.className = 'nav-more-item' + (l.classList.contains('active') ? ' active' : '');\n          item.setAttribute('role', 'menuitem');\n          const text = document.createElement('span'); text.textContent = l.querySelector('.label').textContent; item.appendChild(text);\n          item.addEventListener('click', () => { closeMenu(); l.click(); });\n          menu.appendChild(item);\n        });\n      }\n\n      function openMenu() {\n        const navBox = nav.getBoundingClientRect();\n        const innerBox = inner.getBoundingClientRect();\n        menu.style.right = Math.max(0, navBox.right - innerBox.right) + 'px';\n        menu.hidden = false;\n        nav.classList.add('more-open');\n        more.setAttribute('aria-expanded', 'true');\n        const first = menu.querySelector('.nav-more-item');\n        if (first) first.focus();\n      }\n      function closeMenu() {\n        if (menu.hidden) return;\n        menu.hidden = true;\n        nav.classList.remove('more-open');\n        more.setAttribute('aria-expanded', 'false');\n      }\n\n      more.addEventListener('click', e => {\n        e.stopPropagation();\n        menu.hidden ? openMenu() : closeMenu();\n      });\n      document.addEventListener('click', e => { if (!menu.contains(e.target)) closeMenu(); });\n      document.addEventListener('keydown', e => {\n        if (e.key === 'Escape' && !menu.hidden) { closeMenu(); more.focus(); }\n        if (!menu.hidden && (e.key === 'ArrowDown' || e.key === 'ArrowUp')) {\n          const items = Array.from(menu.querySelectorAll('.nav-more-item'));\n          const i = items.indexOf(document.activeElement);\n          const next = items[(i + (e.key === 'ArrowDown' ? 1 : -1) + items.length) % items.length];\n          if (next) { e.preventDefault(); next.focus(); }\n        }\n      });\n\n      fit();\n      if (window.ResizeObserver) new ResizeObserver(fit).observe(nav);\n      else window.addEventListener('resize', fit);\n      if (document.fonts && document.fonts.ready) document.fonts.ready.then(fit);\n    })();\n  \n\n\n    // ------------------------------------------------------------------\n    // Shared appearance (accent + background) — 2026-09-08, per Martin:\n    // \"wallpapers + accent colors don't save across pages.\" Settings'\n    // Appearance section (and onboarding's Theme step) are the only\n    // writers of schoolagy_appearance; every other real app page,\n    // including this one, applies whatever's saved there, read-only, on\n    // its own load — same shared-localStorage-record pattern already\n    // used for schoolagy_dark_mode/schoolagy_profile.\n    // ------------------------------------------------------------------\n    (function () {\n      function darken(hex, amount) {\n        const n = parseInt(hex.slice(1), 16);\n        const r = Math.max(0, ((n >> 16) & 255) * (1 - amount));\n        const g = Math.max(0, ((n >> 8) & 255) * (1 - amount));\n        const b = Math.max(0, (n & 255) * (1 - amount));\n        return '#' + [r, g, b].map(v => Math.round(v).toString(16).padStart(2, '0')).join('');\n      }\n      function applyAppearance() {\n        let saved = null;\n        try {\n          const raw = localStorage.getItem('schoolagy_appearance');\n          if (raw) saved = JSON.parse(raw);\n        } catch {}\n        if (!saved) return;\n        const root = document.documentElement.style;\n        if (saved.accent) {\n          root.setProperty('--accent', saved.accent);\n          root.setProperty('--accent-dark', saved.accentDark || darken(saved.accent, 0.22));\n        }\n        if (saved.background === 'white') {\n          document.body.style.backgroundImage = 'none';\n          document.body.style.backgroundColor = '#f4f4f6';\n        } else if (saved.background === 'black') {\n          document.body.style.backgroundImage = 'none';\n          document.body.style.backgroundColor = '#0c0c0e';\n        } else if (saved.background) {\n          document.body.style.backgroundImage = `url(\"${saved.background}\")`;\n          document.body.style.backgroundColor = '';\n        }\n      }\n      applyAppearance();\n      window.addEventListener('storage', e => {\n        if (e.key === 'schoolagy_appearance') applyAppearance();\n      });\n    })();\n\n    // ------------------------------------------------------------------\n    // Signed in: real Schoology messages (2026-10-06). TEACHERS and\n    // CONTACTS come from the \"people\" extra and CONVERSATIONS from the\n    // \"messages\" extra (LegacyPage merges both into window.__AVERAGES__.data\n    // before this runs; see scripts/port-pages.mjs). A thread arrives as a\n    // summary with an empty `messages` list and loads when it's opened\n    // (GET /messages/thread). When an extra didn't arrive, the consts below\n    // fall back to their sample literals, which must never pass for a real\n    // student's inbox, so liveSetupPeople/liveSetConversations empty them.\n    // Demo sessions have no live fields and keep the samples, like the\n    // preview. Google Classroom has no messaging at all (see liveInit).\n    // ------------------------------------------------------------------\n    const MSG_AV = window.__AVERAGES__;\n    const MSG_LIVE = !!(MSG_AV && MSG_AV.data && MSG_AV.mode === 'live');\n    const MSG_DATA = MSG_LIVE ? MSG_AV.data : {};\n    const MSG_CLASSROOM = MSG_LIVE && (MSG_DATA.platform === 'classroom' || MSG_DATA.PEOPLE_PLATFORM === 'classroom');\n    const MSG_API = window.location.hostname.endsWith('averages.io') ? 'https://api.averages.io' : 'http://localhost:8787';\n    // Anyone who isn't one of the student's teachers gets this grey.\n    const MSG_NEUTRAL = '#83849a';\n    // The student's teachers, as the people extra sent them. The To search\n    // lists them first; everyone else comes from GET /messages/recipients.\n    const MSG_TEACHER_IDS = new Set(MSG_DATA.TEACHERS && typeof MSG_DATA.TEACHERS === 'object' ? Object.keys(MSG_DATA.TEACHERS) : []);\n    let MSG_PEOPLE = MSG_DATA.MESSAGE_PEOPLE && typeof MSG_DATA.MESSAGE_PEOPLE === 'object' ? MSG_DATA.MESSAGE_PEOPLE : {};\n    let liveInboxState = Array.isArray(MSG_DATA.CONVERSATIONS) ? 'ready' : 'error'; // 'ready' | 'loading' | 'error'\n    let liveRecipientIds = [];\n    let liveRecipientsState = 'idle'; // 'idle' | 'loading' | 'ready' | 'error'\n    let liveRecipientsPromise = Promise.resolve();\n    let liveLocalSeq = 0;\n    let liveNoteTimer = null;\n    let MSG_ME = MSG_DATA.MESSAGES_ME != null ? String(MSG_DATA.MESSAGES_ME) : '';\n\n    function liveText(value, max) {\n      return (value == null ? '' : String(value)).trim().slice(0, max);\n    }\n    // Colors land in style attributes: only a plain hex color gets through.\n    function liveColor(value) {\n      const v = String(value || '').trim();\n      return /^#[0-9a-f]{6}$/i.test(v) ? v : MSG_NEUTRAL;\n    }\n\n    // The people extra's TEACHERS[id].course is a course id, so the line\n    // under a teacher's name is their classes from CONTACTS (or that\n    // course's name from the bundle).\n    function liveSetupPeople() {\n      if (!MSG_DATA.TEACHERS || typeof MSG_DATA.TEACHERS !== 'object') Object.keys(TEACHERS).forEach(k => { delete TEACHERS[k]; });\n      if (!Array.isArray(MSG_DATA.CONTACTS)) CONTACTS.length = 0;\n      const courses = Array.isArray(MSG_DATA.COURSES) ? MSG_DATA.COURSES : [];\n      const contacts = CONTACTS.filter(c => c && c.id != null && String(c.id) !== '').map(c => ({\n        id: String(c.id),\n        name: liveText(c.name, 120) || 'Schoology user',\n        role: liveText(c.role, 80),\n        dept: liveText(c.dept, 200),\n        color: liveColor(c.color),\n      }));\n      CONTACTS.length = 0;\n      contacts.forEach(c => CONTACTS.push(c));\n      Object.keys(TEACHERS).forEach(id => {\n        const t = TEACHERS[id] || {};\n        const contact = contacts.find(c => c.id === id);\n        const course = courses.find(c => c && String(c.id) === String(t.course));\n        TEACHERS[id] = {\n          name: liveText(t.name, 120) || (contact && contact.name) || 'Schoology user',\n          course: (contact && contact.dept) || (course ? liveText(course.name, 200) : ''),\n          color: liveColor(t.color),\n        };\n      });\n    }\n\n    // Every thread's person has an entry in TEACHERS, this page's one lookup\n    // for names and colors: the teacher's own, else the name the messages\n    // extra sent, else \"Schoology user\". Returns the id as a string.\n    function livePerson(id) {\n      const key = id == null ? '' : String(id);\n      if (!TEACHERS[key]) {\n        const known = MSG_PEOPLE[key];\n        const name = known ? liveText(known.name, 120) : '';\n        TEACHERS[key] = { name: name || 'Schoology user', course: '', color: MSG_NEUTRAL, unnamed: !name };\n      }\n      return key;\n    }\n    function personName(id) {\n      return (TEACHERS[id] && TEACHERS[id].name) || 'Schoology user';\n    }\n\n    function liveSetConversations(list) {\n      const next = (Array.isArray(list) ? list : []).filter(c => c && c.id != null && String(c.id) !== '').map(c => {\n        const participants = Array.isArray(c.participants) ? c.participants.map(String) : [];\n        const convo = {\n          id: String(c.id),\n          personId: livePerson(c.personId != null && c.personId !== '' ? c.personId : participants[0]),\n          subject: liveText(c.subject, 200) || 'No subject',\n          unread: !!c.unread,\n          preview: liveText(c.preview, 280),\n          time: liveText(c.time, 40),\n          at: Number(c.at) || 0,\n          participants,\n          messages: [],\n        };\n        Object.assign(convo, deriveMedia(convo));\n        return convo;\n      });\n      CONVERSATIONS.length = 0;\n      next.forEach(c => CONVERSATIONS.push(c));\n    }\n\n    // The newest message, or for a thread that hasn't been opened yet a\n    // stand-in built from its preview.\n    function lastMessageOf(c) {\n      return c.messages[c.messages.length - 1] || { from: 'them', text: c.preview || '', time: c.time || '' };\n    }\n    function rowTimeLabel(c, last) {\n      if (last.sentAt) return relativeTime(last.sentAt);\n      if (MSG_LIVE && c.time) return c.time;\n      return String(last.time || '').split(' · ')[0];\n    }\n    // What search can see of a thread: its loaded messages, else its preview.\n    function searchableMessages(c) {\n      if (c.messages.length) return c.messages.map((m, i) => ({ c, i, m }));\n      return c.preview ? [{ c, i: -1, m: lastMessageOf(c) }] : [];\n    }\n    function threadHasSeveralAuthors(c) {\n      return new Set(c.messages.filter(m => m.from === 'them' && m.authorId).map(m => m.authorId)).size > 1;\n    }\n\n    function liveFetch(path, body) {\n      const init = { method: body ? 'POST' : 'GET', credentials: 'include' };\n      if (body) {\n        init.headers = { 'Content-Type': 'application/json' };\n        init.body = JSON.stringify(body);\n      }\n      return fetch(MSG_API + path, init).then(r => {\n        if (r.ok) return r.json();\n        // The API's reason (e.g. \"recipient_not_allowed\") decides what a\n        // failed send tells the student.\n        return r.json().catch(() => ({})).then(j => {\n          throw Object.assign(new Error('http ' + r.status), { status: r.status, code: j && typeof j.error === 'string' ? j.error : '' });\n        });\n      });\n    }\n\n    // What a failed send says. Retry only where trying again can help: no\n    // connection, Schoology busy or down, or too many messages at once.\n    const LIVE_SEND_ERRORS = {\n      bad_recipients: \"Schoology didn't accept who this is to.\",\n      empty_subject: 'Add a subject first.',\n      subject_too_long: 'The subject is too long (200 characters at most).',\n      empty_message: 'Type a message first.',\n      message_too_long: 'The message is too long (10,000 characters at most).',\n      recipient_not_allowed: \"Your school doesn't let you message this person.\",\n      no_recipients: 'No one is left in this conversation to reply to.',\n      too_many_recipients: 'Too many people are in this conversation to reply here.',\n      rate_limited: 'Too many messages at once. Wait a minute, then retry.',\n    };\n    function liveSendError(err) {\n      const status = err && err.status;\n      if (status === 404) return { text: 'This conversation is gone from Schoology.', retry: false };\n      return {\n        text: LIVE_SEND_ERRORS[err && err.code] || \"Couldn't send.\",\n        retry: !status || status >= 500 || status === 429,\n      };\n    }\n    // Replies go to everyone in the thread (like Schoology's own reply), so\n    // a group thread's composer says so.\n    function liveComposerPlaceholder(c) {\n      const others = c ? (c.participants || []).filter(id => id && id !== MSG_ME).length : 0;\n      composerInput.placeholder = others > 1 ? 'Reply to everyone…' : 'Type a message…';\n    }\n    // Schoology refuses a new message without a subject (400 empty_subject).\n    function liveNeedSubject() {\n      subjectInput.setAttribute('aria-invalid', 'true');\n      subjectInput.focus();\n      showComposerNote('Add a subject first.');\n    }\n\n    function liveInboxStateHtml() {\n      if (liveInboxState === 'loading') return '<p class=\"msgs-empty-hint\" role=\"status\">Loading your messages…</p>';\n      return `<div class=\"msgs-list-state\" role=\"alert\">\n          <p class=\"msgs-list-state-title\">We couldn't load your messages.</p>\n          <p>Schoology didn't answer. Check your connection and try again.</p>\n          <button type=\"button\" class=\"msgs-state-btn\" data-action=\"retry-inbox\">Try again</button>\n        </div>`;\n    }\n    function emptyListHtml() {\n      if (pendingThread) return '';\n      if (MSG_LIVE && !CONVERSATIONS.length) {\n        return `<div class=\"msgs-list-state\">\n            <p class=\"msgs-list-state-title\">No messages yet</p>\n            <p>When a teacher messages you, it shows up here. Use the + button to write to one of your teachers.</p>\n          </div>`;\n      }\n      return `<p class=\"msgs-empty-hint\">No conversations match.</p>`;\n    }\n    function liveRetryInbox() {\n      liveInboxState = 'loading';\n      renderThreadList();\n      liveFetch('/messages').then(data => {\n        if (!data || !Array.isArray(data.CONVERSATIONS)) throw new Error('no conversations');\n        if (data.PEOPLE && typeof data.PEOPLE === 'object') MSG_PEOPLE = data.PEOPLE;\n        if (data.me != null) MSG_ME = String(data.me);\n        // A thread started here that Schoology hasn't confirmed yet stays.\n        const unconfirmed = CONVERSATIONS.filter(c => c.localThread);\n        liveSetConversations(data.CONVERSATIONS);\n        unconfirmed.reverse().forEach(c => CONVERSATIONS.unshift(c));\n        liveInboxState = 'ready';\n      }).catch(() => { liveInboxState = 'error'; }).then(renderThreadList);\n    }\n\n    function liveThreadStateHtml(c, compact) {\n      if (c.load === 'error') {\n        return `<div class=\"msgs-thread-state${compact ? ' compact' : ''}\" role=\"alert\"><p class=\"msgs-empty-hint\">We couldn't load this conversation.</p><button type=\"button\" class=\"msgs-state-btn\" data-action=\"retry-thread\" data-id=\"${escapeHtml(c.id)}\">Try again</button></div>`;\n      }\n      return '<p class=\"msgs-empty-hint\" role=\"status\">Loading messages…</p>';\n    }\n    // Loads a thread's messages once; opening it again uses this copy.\n    // Opening it also marks it read on Schoology (the API does that).\n    function liveLoadThread(c) {\n      if (c.load === 'ready' || c.localThread) return Promise.resolve();\n      if (c.load === 'loading' && c.loading) return c.loading;\n      c.load = 'loading';\n      c.loading = liveFetch('/messages/thread?id=' + encodeURIComponent(c.id)).then(data => {\n        const list = Array.isArray(data && data.messages) ? data.messages : [];\n        const loaded = list.filter(m => m && typeof m === 'object').map(m => {\n          const mine = m.from === 'me';\n          return {\n            from: mine ? 'me' : 'them',\n            authorId: !mine && m.authorId != null && m.authorId !== '' ? livePerson(m.authorId) : '',\n            text: liveText(m.text, 10000),\n            time: liveText(m.time, 60),\n            at: Number(m.at) || 0,\n          };\n        });\n        c.messages = loaded.concat(c.messages.filter(m => m.local));\n        if (Array.isArray(data.participants)) c.participants = data.participants.map(String);\n        c.load = 'ready';\n      }, () => { c.load = 'error'; }).then(() => {\n        c.loading = null;\n        Object.assign(c, deriveMedia(c));\n        liveRefreshThreadView(c);\n        renderThreadList();\n      });\n      return c.loading;\n    }\n    // \"All subjects\" with one person: load their threads one after another.\n    function liveLoadThreads(threads) {\n      threads.reduce((chain, t) => chain.then(() => liveLoadThread(t)), Promise.resolve());\n    }\n    function liveRetryThread(id) {\n      const c = CONVERSATIONS.find(x => x.id === id);\n      if (!c || c.load !== 'error') return;\n      c.load = undefined;\n      liveLoadThread(c);\n      liveRefreshThreadView(c);\n    }\n    // Redraws a thread if it's the one on screen (alone or in All subjects).\n    function liveRefreshThreadView(c) {\n      if (pendingThread) return;\n      if (activeConvoId === c.id) {\n        renderSubjectDropdown(c.personId, c.id);\n        setComposerEnabled(c.load === 'ready', false);\n        liveComposerPlaceholder(c);\n        renderBubbles(c);\n      } else if (viewingAllSubjectsFor && viewingAllSubjectsFor === c.personId) {\n        renderMergedBubbles(threadsForPerson(c.personId));\n      }\n    }\n\n    // Who the student may message (Schoology's own list, already filtered\n    // by the district's rules). Loaded the first time New Message opens;\n    // after a failure the next New Message tries again. Never rejects.\n    function liveLoadRecipients() {\n      if (liveRecipientsState === 'ready' || liveRecipientsState === 'loading') return liveRecipientsPromise;\n      liveRecipientsState = 'loading';\n      liveRecipientsPromise = liveFetch('/messages/recipients').then(data => {\n        const list = Array.isArray(data && data.recipients) ? data.recipients : [];\n        let renamed = false;\n        liveRecipientIds = [];\n        list.forEach(r => {\n          const id = r && r.id != null ? String(r.id) : '';\n          const name = r ? liveText(r.name, 120) : '';\n          if (!/^\\d+$/.test(id) || !name) return;\n          liveRecipientIds.push(id);\n          const t = TEACHERS[id];\n          if (!t) TEACHERS[id] = { name, course: '', color: MSG_NEUTRAL };\n          else if (t.unnamed) { t.name = name; t.unnamed = false; renamed = true; }\n        });\n        liveRecipientsState = 'ready';\n        if (renamed) renderThreadList();\n      }, () => { liveRecipientsState = 'error'; }).then(() => {\n        // The To results were open while this loaded: show the new matches.\n        if (!toResults.hidden && pendingThread && !pendingThread.personId) renderToResults(toInput.value);\n      });\n      return liveRecipientsPromise;\n    }\n    function liveDirectoryMatches(q) {\n      const ids = new Set([...MSG_TEACHER_IDS, ...liveRecipientIds]);\n      return [...ids]\n        .filter(id => TEACHERS[id] && TEACHERS[id].name.toLowerCase().includes(q))\n        .sort((a, b) => ((MSG_TEACHER_IDS.has(b) ? 1 : 0) - (MSG_TEACHER_IDS.has(a) ? 1 : 0)) || TEACHERS[a].name.localeCompare(TEACHERS[b].name))\n        .slice(0, MAX_TO_RESULTS)\n        .map(id => [id, TEACHERS[id]]);\n    }\n    function liveNoMatchText(query) {\n      if (liveRecipientsState === 'loading') return 'Looking for people you can message…';\n      return `No one you can message matches \"${escapeHtml(query)}\".`;\n    }\n    function livePersonIdByName(name) {\n      const want = name.trim().toLowerCase();\n      return [...MSG_TEACHER_IDS, ...liveRecipientIds].find(id => TEACHERS[id] && TEACHERS[id].name.toLowerCase() === want) || '';\n    }\n    // ?compose=<id>&name=&dept=&color= from a course page or Contacts. A\n    // real Schoology id is digits; a course page that couldn't match the\n    // teacher sends a made-up id with their name, so they're found by name.\n    function liveComposeDeepLink(composeId, params) {\n      if (MSG_CLASSROOM) return;\n      const name = liveText(params.get('name'), 120);\n      const realId = /^\\d+$/.test(composeId) ? composeId : '';\n      const known = () => (realId && TEACHERS[realId] ? realId : (name ? livePersonIdByName(name) : ''));\n      const id = known();\n      if (id) { startNewThreadWith(id); return; }\n      // Not known yet: only the recipients list can vouch for an id. The\n      // link's name/dept/color are never trusted as the recipient (2026-10-06 review).\n      liveLoadRecipients().then(() => {\n        if (pendingThread || activeConvoId) return; // they've moved on\n        const found = known();\n        if (found) { startNewThreadWith(found); return; }\n        startComposeMode();\n        if (name) { toInput.value = name; renderToResults(name); }\n      });\n    }\n\n    function showComposerNote(text) {\n      const note = document.getElementById('composerNote');\n      if (!note) return;\n      note.textContent = text;\n      note.hidden = false;\n      clearTimeout(liveNoteTimer);\n      liveNoteTimer = setTimeout(() => { note.hidden = true; }, 4000);\n    }\n\n    // Sending, signed in. The message shows right away as \"Sending…\", then\n    // \"Just now\", or \"Not sent\" with Retry. A pasted link still shows as a\n    // link here but goes to Schoology as plain text, exactly as typed.\n    function liveSendComposerMessage() {\n      const raw = composerInput.value.trim().slice(0, 10000);\n      if (!raw) return;\n      if (pendingThread && !pendingThread.personId) { toInput.focus(); return; }\n      const { text, linkAttachment } = extractLinkAttachment(raw);\n      const msg = { from: 'me', text, time: 'Sending…', body: raw, local: true, localId: `m${++liveLocalSeq}` };\n      if (linkAttachment) msg.attachments = [linkAttachment];\n      let c;\n      if (pendingThread) {\n        const personId = pendingThread.personId;\n        const subject = (pendingThread.subject || '').trim().slice(0, 200);\n        if (!subject) { liveNeedSubject(); return; }\n        c = { id: `local-${Date.now()}`, personId, subject, unread: false, preview: '', time: '', at: Date.now(), participants: [personId], messages: [msg], load: 'ready', localThread: true };\n        msg.create = { recipientIds: [personId], subject };\n        CONVERSATIONS.unshift(c);\n        pendingThread = null;\n        activeConvoId = c.id;\n      } else {\n        c = CONVERSATIONS.find(x => x.id === activeConvoId);\n        if (!c || c.load !== 'ready') return;\n        c.messages.push(msg);\n        // Newest first, like the inbox.\n        CONVERSATIONS.splice(CONVERSATIONS.indexOf(c), 1);\n        CONVERSATIONS.unshift(c);\n      }\n      Object.assign(c, deriveMedia(c));\n      composerInput.value = '';\n      composerInput.classList.remove('msgs-composer-link-active');\n      showThread(c);\n      renderThreadList();\n      liveDeliver(c, msg);\n    }\n    function liveDeliver(c, msg) {\n      msg.status = 'sending';\n      msg.time = 'Sending…';\n      msg.sentAt = undefined;\n      msg.error = '';\n      liveRefreshThreadView(c);\n      let request;\n      if (msg.create) {\n        request = c.creating = liveFetch('/messages', { recipientIds: msg.create.recipientIds, subject: msg.create.subject, message: msg.body }).then(res => {\n          if (!res || res.ok === false) throw new Error('not sent');\n          delete msg.create;\n          // With Schoology's id, replies in this thread go to that thread.\n          const id = res.id != null ? String(res.id) : '';\n          if (/^\\d+$/.test(id)) {\n            if (activeConvoId === c.id) activeConvoId = id;\n            c.id = id;\n            c.localThread = false;\n          }\n        });\n      } else {\n        // A reply in a thread started here waits for the thread to exist.\n        request = (c.creating || Promise.resolve()).catch(() => {}).then(() => {\n          if (c.localThread) throw new Error('thread not created');\n          return liveFetch('/messages/reply', { id: c.id, message: msg.body });\n        }).then(res => { if (!res || res.ok === false) throw new Error('not sent'); });\n      }\n      request.then(() => {\n        msg.status = 'sent';\n        msg.sentAt = Date.now();\n        msg.time = 'Just now';\n      }, err => {\n        const why = liveSendError(err);\n        msg.status = 'failed';\n        msg.time = 'Not sent';\n        msg.error = why.text;\n        msg.canRetry = why.retry;\n      }).then(() => {\n        liveRefreshThreadView(c);\n        renderThreadList();\n      });\n    }\n    function liveRetryMessage(localId) {\n      for (const c of CONVERSATIONS) {\n        const msg = c.messages.find(m => m.localId === localId);\n        if (msg && msg.status === 'failed') { liveDeliver(c, msg); return; }\n      }\n    }\n\n    function liveInit() {\n      msgsShell.classList.add('live');\n      composerInput.maxLength = 10000;\n      subjectInput.maxLength = 200;\n      subjectInput.required = true;\n      subjectInput.placeholder = 'Subject (required)';\n      subjectInput.addEventListener('input', () => subjectInput.removeAttribute('aria-invalid'));\n      threadList.addEventListener('click', e => {\n        if (e.target.closest('[data-action=\"retry-inbox\"]')) liveRetryInbox();\n      });\n      if (MSG_CLASSROOM) {\n        msgsShell.classList.add('no-messaging');\n        const emo = threadEmpty.querySelector('.emo');\n        threadEmpty.textContent = '';\n        if (emo) threadEmpty.appendChild(emo);\n        threadEmpty.insertAdjacentHTML('beforeend', `\n          <p class=\"msgs-no-messaging-title\">Google Classroom doesn't have messages.</p>\n          <p class=\"hint\">Your teachers' announcements are on Home and each class page.</p>\n          <a class=\"msgs-state-btn\" href=\"/home\">Go to Home</a>`);\n        updateSubtitle();\n      }\n    }\n\n    // ------------------------------------------------------------------\n    // Sample data — same six teachers/course colors as /grades's\n    // COURSES array, duplicated locally per this project's established\n    // cross-page convention (see architecture-decisions.md's\n    // shared-stylesheet note). Two conversations start unread to\n    // demonstrate that state; the rest are already read.\n    // ------------------------------------------------------------------\n    // Teachers a user can message, keyed by id — this is the source both\n    // the New Message people-list and every conversation's identity\n    // (avatar/name/course) read from. Separated from CONVERSATIONS below\n    // per Martin's 2026-09-01 question about supporting multiple separate\n    // message THREADS with the same person (a real Schoology behavior) —\n    // a person and a thread are no longer the same thing: TEACHERS is the\n    // person directory, CONVERSATIONS is a list of threads that each\n    // reference one person by id via `personId`, so the same person can\n    // have any number of threads (see the two Mr. Cho threads below).\n    const TEACHERS = (window.__AVERAGES__ && window.__AVERAGES__.data && window.__AVERAGES__.data.TEACHERS) || {\n      cho: { name: 'Mr. Cho', course: 'English 10', color: '#6b8f5e' },\n      alvarez: { name: 'Mr. Alvarez', course: 'AP Chemistry', color: '#a67a22' },\n      whitfield: { name: 'Ms. Whitfield', course: 'Algebra II', color: '#5b6ea3' },\n      bennett: { name: 'Mrs. Bennett', course: 'U.S. History', color: '#a15c4f' },\n      ortiz: { name: 'Sra. Ortiz', course: 'Spanish III', color: '#8a6ba1' },\n      reyes: { name: 'Coach Reyes', course: 'PE', color: '#4f8c8a' },\n    };\n\n    // Full district directory — duplicated from /contacts's own\n    // CONTACTS array (same ids/names/colors for the 6 people also in\n    // TEACHERS above), per this project's established cross-page\n    // sample-data convention. Added 2026-09-04 (per Martin) so the New\n    // Message \"To\" dropdown can offer every person from Contacts, not\n    // just current teachers -- previously only reachable one at a time\n    // via a deep link from /contacts itself (see\n    // handleComposeDeepLink further down). Every entry not already a key\n    // in TEACHERS gets folded in right below (using `dept` as that\n    // person's `course` field, same fallback handleComposeDeepLink\n    // already used) so person()/avatarBg()/the To dropdown all keep\n    // reading from the one TEACHERS lookup regardless of where a\n    // recipient came from.\n    const CONTACTS = (window.__AVERAGES__ && window.__AVERAGES__.data && window.__AVERAGES__.data.CONTACTS) || [\n      { id: 'cho', name: 'Mr. Cho', role: 'Teacher', dept: 'English Department', color: '#6b8f5e' },\n      { id: 'alvarez', name: 'Mr. Alvarez', role: 'Teacher', dept: 'Science Department', color: '#a67a22' },\n      { id: 'whitfield', name: 'Ms. Whitfield', role: 'Teacher', dept: 'Math Department', color: '#5b6ea3' },\n      { id: 'bennett', name: 'Mrs. Bennett', role: 'Teacher', dept: 'Social Studies Department', color: '#a15c4f' },\n      { id: 'ortiz', name: 'Sra. Ortiz', role: 'Teacher', dept: 'World Languages Department', color: '#8a6ba1' },\n      { id: 'reyes', name: 'Coach Reyes', role: 'Teacher', dept: 'Physical Education Department', color: '#4f8c8a' },\n      { id: 'patterson', name: 'Ms. Patterson', role: 'Teacher', dept: 'Science Department', color: '#7a8f4f' },\n      { id: 'delgado', name: 'Mr. Delgado', role: 'Teacher', dept: 'Math Department', color: '#5b7ea3' },\n      { id: 'nakamura-t', name: 'Mrs. Nakamura', role: '', dept: 'English Department', color: '#8f6b7a' },\n      { id: 'simmons', name: 'Dr. Simmons', role: 'Principal', dept: 'Administration', color: '#946b3e' },\n      { id: 'osei', name: 'Mrs. Osei', role: 'Assistant Principal', dept: 'Administration', color: '#6b8f8f' },\n      { id: 'foster', name: 'Ms. Foster', role: 'School Counselor', dept: 'Counseling', color: '#6b7a9c' },\n      { id: 'okafor', name: 'Mr. Okafor', role: '', dept: 'Counseling', color: '#9c6b8a' },\n      { id: 'lindqvist', name: 'Mrs. Lindqvist', role: 'Librarian', dept: 'Media Center', color: '#7a7050' },\n      { id: 'ramirez', name: 'Nurse Ramirez', role: 'School Nurse', dept: 'Health Office', color: '#a15c5c' },\n      { id: 'yusuf', name: 'Mr. Yusuf', role: '', dept: 'Athletics', color: '#4f7a5c' },\n      { id: 'whitmore', name: 'Dr. Whitmore', role: 'Superintendent', dept: 'District Office', color: '#5c5c8a' },\n      { id: 'alvarado', name: 'Ms. Alvarado', role: 'IT Help Desk', dept: 'District Office', color: '#4f7d8f' },\n      { id: 'chen', name: 'Mr. Chen', role: 'Director of Special Education', dept: 'District Office', color: '#8f6b4f' },\n    ];\n    // Signed in: real people only, never the sample directory (2026-10-06).\n    if (MSG_LIVE) liveSetupPeople();\n    CONTACTS.forEach(c => {\n      if (!TEACHERS[c.id]) TEACHERS[c.id] = { name: c.name, course: c.dept, color: c.color };\n    });\n\n    // Each thread has a `subject` (shown in the thread list/header so two\n    // threads with the same person read as distinct, the same way email\n    // subjects do) and, new this round, `docs`/`links`/`video`/`audio`\n    // arrays alongside `messages` — sample \"shared in this thread\" content\n    // for the new categorized search panel below (see searchCategories).\n    // Docs/links/video/audio (2026-09-02): each thread's docs/links/video/\n    // audio arrays used to be hand-authored separately from its messages,\n    // which let them drift out of sync with what the messages actually\n    // say — e.g. a \"Docs\" entry for a file nobody ever sent in the chat,\n    // just a teacher mentioning an assignment that lives in Course\n    // Materials. Per Martin: \"Docs\" should mean something someone\n    // actually UPLOADED in the conversation, not an assignment merely\n    // mentioned in passing. So these arrays are no longer hand-authored\n    // here at all — they're derived from an `attachment` field on the\n    // specific message that shares that item (see deriveMedia() right\n    // after this array), and that message renders the attachment inline\n    // in the thread view too (see renderBubbleAttachment), so what\n    // search surfaces always matches something visibly shared in that\n    // chat. A message that just references an assignment living\n    // elsewhere (Alvarez's \"nice work on the titration lab\", Bennett's\n    // \"posted in Course Materials\") stays plain text with no attachment\n    // — those aren't chat uploads and don't belong in Docs.\n    const CONVERSATIONS = (window.__AVERAGES__ && window.__AVERAGES__.data && window.__AVERAGES__.data.CONVERSATIONS) || [\n      { id: 'cho-essay', personId: 'cho', subject: 'Essay Extension', unread: true, messages: [\n        { from: 'me', text: \"Could I get an extension on the rhetorical analysis essay? I was out sick Tuesday — here's my draft so far.\", time: 'Yesterday · 4:12 PM', attachment: { kind: 'doc', name: 'Rhetorical_Analysis_Draft.docx' } },\n        { from: 'them', text: 'Of course — Friday work for you?', time: 'Yesterday · 4:30 PM' },\n        { from: 'me', text: 'That works, thank you so much!', time: 'Yesterday · 4:31 PM' },\n      ] },\n      // Second thread with the SAME teacher (Mr. Cho), on an unrelated\n      // topic — demonstrates that a person can have more than one active\n      // conversation at once, per Martin's question about this.\n      { id: 'cho-bookclub', personId: 'cho', subject: 'After-School Book Club', unread: false, messages: [\n        { from: 'them', text: \"Quick heads up — Book Club meets in room 214 today instead of the library. Here's the sign-up sheet if you haven't added your name yet:\", time: 'Mon, Aug 24 · 8:10 AM', attachment: { kind: 'link', title: 'Book Club sign-up sheet', url: 'forms.gle/bookclub24' } },\n        { from: 'me', text: 'Got it, see you there!', time: 'Mon, Aug 24 · 8:12 AM' },\n      ] },\n      { id: 'alvarez-unit2', personId: 'alvarez', subject: 'Unit 2 Test Corrections', unread: true, messages: [\n        { from: 'them', text: \"Hi! Just a reminder the Unit 2 test corrections are due Friday. Here's the simulation again if you want extra practice:\", time: 'Mon, Aug 24 · 9:02 AM', attachment: { kind: 'link', title: 'PhET Titration Simulation', url: 'phet.colorado.edu/titration' } },\n        { from: 'me', text: 'Got it, thank you!', time: 'Mon, Aug 24 · 9:15 AM' },\n        { from: 'them', text: 'Also — nice work on the titration lab, one of the best write-ups this term.', time: 'Yesterday · 3:40 PM' },\n      ] },\n      { id: 'whitfield-quiz6', personId: 'whitfield', subject: 'Quiz 6 Reschedule', unread: false, messages: [\n        { from: 'them', text: \"Quiz 6 has been pushed to next Tuesday to give everyone more review time. Here are some practice graphs to use while you wait:\", time: 'Yesterday · 11:20 AM', attachment: { kind: 'link', title: 'Desmos — Quiz 6 practice graphs', url: 'desmos.com/calculator/quiz6' } },\n      ] },\n      { id: 'bennett-dbq', personId: 'bennett', subject: 'DBQ Essay Rubric', unread: false, messages: [\n        { from: 'them', text: 'The DBQ essay rubric is posted in Course Materials if you want to look it over before you revise.', time: 'Tue, Aug 25 · 1:10 PM' },\n      ] },\n      { id: 'ortiz-vocab', personId: 'ortiz', subject: 'Vocabulario Exam', unread: false, messages: [\n        { from: 'them', text: '¡Buen trabajo en el examen de vocabulario! Keep it up. Aquí tienes un audio de práctica:', time: 'Mon, Aug 24 · 2:05 PM', attachment: { kind: 'audio', name: 'Pronunciación — Unidad 3', duration: '0:48' } },\n        { from: 'me', text: '¡Gracias, Sra. Ortiz!', time: 'Mon, Aug 24 · 2:40 PM' },\n      ] },\n      { id: 'reyes-fitness', personId: 'reyes', subject: 'Fitness Test Reminder', unread: false, messages: [\n        { from: 'them', text: 'Don’t forget — bring sneakers for the fitness test Thursday. Here’s a quick warm-up to run through beforehand:', time: 'Fri, Aug 21 · 10:00 AM', attachment: { kind: 'video', name: 'Warm-up routine demo', duration: '1:12' } },\n      ] },\n    ];\n\n    // A message carries its attachment(s) as either the older singular\n    // `attachment` field (every hand-authored CONVERSATIONS message\n    // above) or, since 2026-09-04 (per Martin: composer now supports\n    // picking more than one file at once), a plural `attachments` array\n    // (every message sent through the composer — see sendComposerMessage\n    // further down). This normalizes either shape to an array so\n    // everything downstream (deriveMedia, renderBubbles) only has to\n    // handle one case.\n    function attachmentsOf(m) {\n      if (Array.isArray(m.attachments)) return m.attachments;\n      if (m.attachment) return [m.attachment];\n      return [];\n    }\n\n    // Builds each thread's docs/links/video/audio arrays from its\n    // messages' attachment(s) (see attachmentsOf() above and the comment\n    // above CONVERSATIONS) — single source of truth, so search can never\n    // surface something that isn't also visible as an attachment in the\n    // thread itself.\n    function deriveMedia(c) {\n      const docs = [], links = [], video = [], audio = [];\n      c.messages.forEach(m => {\n        attachmentsOf(m).forEach(a => {\n          if (a.kind === 'doc') docs.push({ name: a.name, time: m.time });\n          else if (a.kind === 'link') links.push({ title: a.title, url: a.url, time: m.time });\n          else if (a.kind === 'video') video.push({ name: a.name, duration: a.duration, time: m.time });\n          else if (a.kind === 'audio') audio.push({ name: a.name, duration: a.duration, time: m.time });\n        });\n      });\n      return { docs, links, video, audio };\n    }\n    // Signed in: the real inbox, or nothing (it failed, see\n    // liveInboxState), never the sample threads (2026-10-06).\n    if (MSG_LIVE) liveSetConversations(Array.isArray(MSG_DATA.CONVERSATIONS) ? MSG_DATA.CONVERSATIONS : null);\n    CONVERSATIONS.forEach(c => Object.assign(c, deriveMedia(c)));\n\n    function person(c) { return TEACHERS[c.personId]; }\n\n    function avatarInitial(name) {\n      const parts = String(name).trim().split(' ');\n      // A blank live name has no letter to show (2026-10-06).\n      return (parts[parts.length - 1][0] || '?').toUpperCase();\n    }\n    /**\n     * Escapes a value for interpolation into an HTML string.\n     *\n     * CONVERSATIONS/TEACHERS are replaced at build time with live Schoology\n     * data — and on this page a classmate controls it directly, since anyone\n     * who can message the student picks their own display name and message\n     * text. Dropping that into an `.innerHTML` template would let a sender\n     * named `<img src=x onerror=...>` execute in our origin, so every data\n     * slot goes through here, in quoted attributes as well as text.\n     *\n     * Coerces with String() rather than assuming a string: epoch timestamps\n     * and other numeric fields reach this in attribute positions, and nothing\n     * shape-checks the live bundle on the way in (the old `str.replace` body\n     * threw outright on a number).\n     *\n     * NOTE: do not wrap values that are themselves HTML — timeSpanHtml(),\n     * renderBubbleRowHtml(), draftBubblesPlaceholder(), newMessageRowHtml(),\n     * highlightMatch() (it escapes internally) and the ICON_* constants all\n     * return markup on purpose, and escaping them would print visible tags.\n     */\n    function escapeHtml(value) {\n      return String(value).replace(/[&<>\"']/g, ch => (\n        { '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[ch]\n      ));\n    }\n\n    // ------------------------------------------------------------------\n    // Live-updating relative timestamps (2026-09-04, per Martin: \"update\n    // timestamps every min, also on page reload\"). Only messages actually\n    // sent through the composer this session carry a real `sentAt` (epoch\n    // ms, set in sendComposerMessage) — every hand-authored CONVERSATIONS\n    // message above has a fixed historical-looking string instead (e.g.\n    // \"Yesterday · 4:12 PM\") and is left alone, since those are supposed\n    // to read as fixed points in the past, not drift. For a message that\n    // does have `sentAt`, relativeTime() computes the label fresh, and\n    // any span rendered via timeSpanHtml() carries a `data-sent-at`\n    // attribute so tickRelativeTimes() (below, run once immediately and\n    // then every 60s) can refresh just that span's text in place —\n    // deliberately NOT a full re-render of the thread/bubbles, so a tick\n    // never resets scroll position or disrupts anything else on screen.\n    // ------------------------------------------------------------------\n    function relativeTime(ms) {\n      const diffSec = Math.max(0, Math.floor((Date.now() - ms) / 1000));\n      if (diffSec < 60) return 'Just now';\n      const diffMin = Math.floor(diffSec / 60);\n      if (diffMin < 60) return `${diffMin} min${diffMin === 1 ? '' : 's'} ago`;\n      const diffHr = Math.floor(diffMin / 60);\n      if (diffHr < 24) return `${diffHr} hour${diffHr === 1 ? '' : 's'} ago`;\n      const diffDay = Math.floor(diffHr / 24);\n      return `${diffDay} day${diffDay === 1 ? '' : 's'} ago`;\n    }\n    function timeSpanHtml(label, sentAt, cls) {\n      return `<span class=\"${cls}\"${sentAt ? ` data-sent-at=\"${escapeHtml(sentAt)}\"` : ''}>${escapeHtml(label)}</span>`;\n    }\n    function tickRelativeTimes() {\n      document.querySelectorAll('[data-sent-at]').forEach(el => {\n        el.textContent = relativeTime(Number(el.dataset.sentAt));\n      });\n    }\n    setInterval(tickRelativeTimes, 60000);\n    // Teacher \"profile photo\" (2026-09-01 follow-up: Martin asked for this\n    // to come from the API/app auth rather than a stock image service). In\n    // the real app this is GET /v1/users/{id}/photo — an endpoint gated\n    // behind the signed-in session, same as every other Messages call this\n    // mock documents (see the CSS comment above .msgs-shell). A static,\n    // backend-less HTML file has no session to authenticate with, so it\n    // can't literally call that endpoint; the earlier version of this page\n    // used a public placeholder-photo service (pravatar.cc) as a stand-in,\n    // but that's an unauthenticated third-party API, not \"the app's auth,\"\n    // so it's gone. Instead every teacher gets a generated color-gradient\n    // \"photo card\" with their initial — this is the same fallback avatar\n    // real apps (Google, Outlook, Slack) show before a real photo has\n    // synced, so it's an honest placeholder rather than a fake photo, and\n    // it needs no network call at all (works instantly, even offline).\n    function shadeColor(hex, percent) {\n      const num = parseInt(hex.slice(1), 16);\n      const clamp = v => Math.max(0, Math.min(255, v));\n      const r = clamp((num >> 16) + Math.round(255 * percent));\n      const g = clamp(((num >> 8) & 0xff) + Math.round(255 * percent));\n      const b = clamp((num & 0xff) + Math.round(255 * percent));\n      return '#' + (0x1000000 + r * 0x10000 + g * 0x100 + b).toString(16).slice(1);\n    }\n    // Takes a person/teacher object ({name, color, ...}), not a thread.\n    function avatarBg(p) {\n      return `linear-gradient(135deg, ${p.color}, ${shadeColor(p.color, -0.26)})`;\n    }\n\n    let activeConvoId = null;\n    // Set while a New Message draft is in progress -- see\n    // startComposeMode()/startNewThreadWith()/resumeComposeMode() below.\n    // { personId, subject }, with personId null until chosen in the To\n    // dropdown. Nothing is added to CONVERSATIONS until the first message\n    // is actually sent, so re-opening New Message never creates empty\n    // duplicate threads.\n    let pendingThread = null;\n    let currentFilter = 'all'; // 'all' | 'unread' | 'combined'\n    let searchQuery = '';\n\n    function convoTextMatches(c, q) {\n      // Signed in, a thread that hasn't been opened yet only has its\n      // preview to search (2026-10-06).\n      return c.messages.some(m => m.text.toLowerCase().includes(q)) || (!!c.preview && c.preview.toLowerCase().includes(q));\n    }\n\n    function filteredConversations() {\n      const list = CONVERSATIONS.filter(c => {\n        if (currentFilter === 'unread' && !c.unread) return false;\n        if (searchQuery) {\n          const q = searchQuery.toLowerCase();\n          const p = person(c);\n          const nameMatch = p.name.toLowerCase().includes(q) || p.course.toLowerCase().includes(q) || c.subject.toLowerCase().includes(q);\n          if (!nameMatch && !convoTextMatches(c, q)) return false;\n        }\n        return true;\n      });\n      // Pinned conversations float to the top (2026-09-04, per Martin,\n      // right-click a row > Pin). Array.prototype.sort is stable\n      // (ES2019+), so conversations keep their existing relative order\n      // within each of the two groups -- this never reshuffles anything\n      // beyond promoting pinned rows.\n      return list.sort((a, b) => (b.pinned ? 1 : 0) - (a.pinned ? 1 : 0));\n    }\n\n    // \"Combined\" filter (2026-09-05, per Martin: picking this option from\n    // the filter dropdown next to search should automatically merge every\n    // person's separate subject threads into a single row, rather than\n    // listing each subject as its own row). One row per person instead of\n    // one row per thread -- reuses the exact same merged \"All subjects\"\n    // timeline already built for the per-person subject dropdown\n    // (showAllSubjectsFor/renderMergedBubbles), just reached from the\n    // thread list directly instead of via that dropdown.\n    //\n    // \"Most recent\" thread per person: this app's sample data has no\n    // reliable global timestamp to sort by (older messages only have a\n    // display string like \"Yesterday · 4:12 PM\", not a real Date) -- so,\n    // matching how filteredConversations() above already treats\n    // CONVERSATIONS' existing array order as newest-first (new threads are\n    // unshift()'d onto the front in sendComposerMessage()), this just\n    // takes each person's FIRST-encountered thread in that same order as\n    // their \"most recent\" for the row's time/preview text.\n    function combinedRows() {\n      const byPerson = new Map();\n      for (const c of CONVERSATIONS) {\n        if (searchQuery) {\n          const q = searchQuery.toLowerCase();\n          const p = person(c);\n          const nameMatch = p.name.toLowerCase().includes(q) || p.course.toLowerCase().includes(q) || c.subject.toLowerCase().includes(q);\n          if (!nameMatch && !convoTextMatches(c, q)) continue;\n        }\n        if (!byPerson.has(c.personId)) byPerson.set(c.personId, []);\n        byPerson.get(c.personId).push(c);\n      }\n      const rows = [...byPerson.entries()].map(([personId, threads]) => ({\n        personId,\n        threads,\n        primary: threads[0],\n        unread: threads.some(t => t.unread),\n        pinned: threads.some(t => t.pinned),\n      }));\n      // Same pinned-floats-to-top rule as filteredConversations() -- if\n      // any of a person's threads is pinned, their combined row is too.\n      return rows.sort((a, b) => (b.pinned ? 1 : 0) - (a.pinned ? 1 : 0));\n    }\n\n    function combinedRowHtml(row) {\n      const p = person(row.primary);\n      const last = lastMessageOf(row.primary);\n      const lastTimeLabel = rowTimeLabel(row.primary, last);\n      const isMulti = row.threads.length > 1;\n      // A person with only one thread shows their real subject, same as a\n      // normal row -- only an actual merge gets the \"N conversations\"\n      // summary line, since no single subject applies once there's more\n      // than one.\n      const subjectLine = isMulti ? `${row.threads.length} conversations` : row.primary.subject;\n      const isActive = row.threads.some(t => t.id === activeConvoId) || viewingAllSubjectsFor === row.personId;\n      return `\n        <div class=\"msgs-thread-row ${row.unread ? 'unread' : ''} ${isActive ? 'active' : ''}\" data-id=\"${escapeHtml(row.primary.id)}\" data-person-id=\"${escapeHtml(row.personId)}\" data-combined=\"${isMulti ? '1' : '0'}\" tabindex=\"0\" role=\"button\" aria-label=\"Open conversation with ${escapeHtml(p.name)}${row.pinned ? ' (pinned)' : ''}${isMulti ? `, ${row.threads.length} combined conversations` : ''}\">\n          <span class=\"msgs-avatar\" style=\"background:${escapeHtml(avatarBg(p))}\">${escapeHtml(avatarInitial(p.name))}</span>\n          <div class=\"msgs-thread-row-text\">\n            <div class=\"msgs-thread-row-top\">\n              <span class=\"msgs-thread-row-name\">${row.pinned ? `<span class=\"msgs-pin-icon\" aria-hidden=\"true\">${ICON_PIN}</span>` : ''}${escapeHtml(p.name)}</span>\n              ${timeSpanHtml(lastTimeLabel, last.sentAt, 'msgs-thread-row-time')}\n            </div>\n            <div class=\"msgs-thread-row-subject\">${escapeHtml(subjectLine)}</div>\n            <div class=\"msgs-thread-row-preview\">${last.from === 'me' ? 'You: ' : ''}${escapeHtml(last.text)}</div>\n          </div>\n          ${row.unread ? '<span class=\"msgs-unread-dot\" aria-hidden=\"true\"></span>' : ''}\n        </div>\n      `;\n    }\n\n    function updateSubtitle() {\n      // Nothing to count while the live inbox is loading or failed, or on\n      // Google Classroom (2026-10-06).\n      if (MSG_LIVE && (MSG_CLASSROOM || liveInboxState !== 'ready')) {\n        document.getElementById('msgsSubtitle').textContent = '';\n        return;\n      }\n      const n = CONVERSATIONS.filter(c => c.unread).length;\n      document.getElementById('msgsSubtitle').textContent = n > 0 ? `${n} unread` : 'All caught up';\n    }\n\n    const threadList = document.getElementById('threadList');\n    // The pinned \"New Message\" draft row (2026-09-04, per Martin: \"the\n    // people that are alr there stay there, make a New Message line...\n    // name it New Message\"). Rendered at the top of the SAME thread list\n    // -- existing conversations are never hidden or swapped out for a\n    // separate picker anymore -- whenever a compose draft is in\n    // progress (pendingThread set, see startComposeMode/\n    // startNewThreadWith/resumeComposeMode below). Formatted like a\n    // normal thread row (avatar + name line + optional subject line) so\n    // it reads as one of the list, just with \"New Message\" standing in\n    // for a person's name and a generic \"+\" avatar since no recipient\n    // may be chosen yet.\n    function newMessageRowHtml() {\n      if (!pendingThread) return '';\n      return `\n        <div class=\"msgs-thread-row active new-message\" data-id=\"__new__\" tabindex=\"0\" role=\"button\" aria-label=\"New Message draft\">\n          <span class=\"msgs-avatar msgs-avatar-new\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M12 5v14M5 12h14\"/></svg></span>\n          <div class=\"msgs-thread-row-text\">\n            <div class=\"msgs-thread-row-top\">\n              <span class=\"msgs-thread-row-name\">New Message</span>\n            </div>\n            ${pendingThread.subject ? `<div class=\"msgs-thread-row-subject\">${escapeHtml(pendingThread.subject)}</div>` : ''}\n          </div>\n        </div>\n      `;\n    }\n    function renderThreadList() {\n      // Signed in, the inbox can still be loading, or have failed (2026-10-06).\n      if (MSG_LIVE && liveInboxState !== 'ready') {\n        threadList.innerHTML = newMessageRowHtml() + liveInboxStateHtml();\n        updateSubtitle();\n        return;\n      }\n      // \"Combined\" (2026-09-05, per Martin) takes a completely different\n      // shape -- one row per person instead of one row per thread -- so it\n      // gets its own render path via combinedRows()/combinedRowHtml()\n      // rather than being squeezed into the per-thread list below.\n      if (currentFilter === 'combined') {\n        const rows = combinedRows();\n        const body = rows.length ? rows.map(combinedRowHtml).join('') : emptyListHtml();\n        threadList.innerHTML = newMessageRowHtml() + body;\n        updateSubtitle();\n        return;\n      }\n      const list = filteredConversations();\n      const body = list.length ? list.map(c => {\n        const p = person(c);\n        const last = lastMessageOf(c);\n        const lastTimeLabel = rowTimeLabel(c, last);\n        return `\n          <div class=\"msgs-thread-row ${c.unread ? 'unread' : ''} ${c.id === activeConvoId ? 'active' : ''}\" data-id=\"${escapeHtml(c.id)}\" tabindex=\"0\" role=\"button\" aria-label=\"Open ${escapeHtml(c.subject)} with ${escapeHtml(p.name)}${c.pinned ? ' (pinned)' : ''}\">\n            <span class=\"msgs-avatar\" style=\"background:${escapeHtml(avatarBg(p))}\">${escapeHtml(avatarInitial(p.name))}</span>\n            <div class=\"msgs-thread-row-text\">\n              <div class=\"msgs-thread-row-top\">\n                <span class=\"msgs-thread-row-name\">${c.pinned ? `<span class=\"msgs-pin-icon\" aria-hidden=\"true\">${ICON_PIN}</span>` : ''}${escapeHtml(p.name)}</span>\n                ${timeSpanHtml(lastTimeLabel, last.sentAt, 'msgs-thread-row-time')}\n              </div>\n              <div class=\"msgs-thread-row-subject\">${escapeHtml(c.subject)}</div>\n              <div class=\"msgs-thread-row-preview\">${last.from === 'me' ? 'You: ' : ''}${escapeHtml(last.text)}</div>\n            </div>\n            ${c.unread ? '<span class=\"msgs-unread-dot\" aria-hidden=\"true\"></span>' : ''}\n          </div>\n        `;\n      }).join('') : emptyListHtml();\n      threadList.innerHTML = newMessageRowHtml() + body;\n      updateSubtitle();\n    }\n\n    const threadEmpty = document.getElementById('threadEmpty');\n    const threadActive = document.getElementById('threadActive');\n    const threadIdentity = document.getElementById('threadIdentity');\n    const threadAvatar = document.getElementById('threadAvatar');\n    const threadName = document.getElementById('threadName');\n    const threadCourse = document.getElementById('threadCourse');\n    const threadSubjectRow = document.getElementById('threadSubjectRow');\n    const threadSubjectTrigger = document.getElementById('threadSubjectTrigger');\n    const threadSubjectTriggerLabel = document.getElementById('threadSubjectTriggerLabel');\n    const threadSubjectMenu = document.getElementById('threadSubjectMenu');\n    const composerHint = document.getElementById('composerHint');\n    const sendBtn = document.getElementById('sendBtn');\n    // Set only while the merged \"All subjects\" view is open (see\n    // showAllSubjectsFor) -- the personId being viewed, so the subject\n    // dropdown can tell it apart from a single real thread (activeConvoId).\n    let viewingAllSubjectsFor = null;\n    const toBar = document.getElementById('toBar');\n    const toInput = document.getElementById('toInput');\n    const toResults = document.getElementById('toResults');\n    const subjectBar = document.getElementById('subjectBar');\n    const subjectInput = document.getElementById('subjectInput');\n    const threadBubbles = document.getElementById('threadBubbles');\n    const composerForm = document.getElementById('composerForm');\n    const composerInput = document.getElementById('composerInput');\n    const msgsShell = document.getElementById('msgsShell');\n\n    // ------------------------------------------------------------------\n    // Attach button (2026-09-02, per Martin) — sits next to Send in the\n    // composer. Opens the OS file picker (a native <input type=\"file\">\n    // is the standard, reliable way to do this — unlike the native\n    // color picker swapped out elsewhere in the app, there's no\n    // cross-browser inconsistency to work around here); picked files are\n    // held in `pendingAttachments` and previewed above the composer\n    // until the message is actually sent (or a tile's × is clicked), at\n    // which point they're attached to that message the same way a\n    // message with real shared files works everywhere else (see\n    // `attachments`/`attachment` on CONVERSATIONS messages,\n    // attachmentsOf(), and renderBubbleAttachment) — so an attachment\n    // sent this way shows up in the thread and in search's Docs category\n    // exactly like the pre-authored ones do. Only each file's name is\n    // used (this is a front-end mock with nowhere to actually upload a\n    // file to); size/type aren't read.\n    // 2026-09-04 (per Martin, with a Claude-attachment-UI screenshot as\n    // reference): the file input now accepts multiple files at once\n    // (`multiple` attribute), and `pendingAttachments` is an array\n    // instead of a single object — each entry renders as its own small\n    // square tile with its own remove button (see the CSS above), rather\n    // than one attachment replacing the last. Real document preview\n    // (thumbnails) is intentionally not implemented per Martin (\"will\n    // come out in later version\") — each tile is just filename + a small\n    // extension badge.\n    // ------------------------------------------------------------------\n    const attachBtn = document.getElementById('attachBtn');\n    const attachFileInput = document.getElementById('attachFileInput');\n    const pendingAttachmentBar = document.getElementById('pendingAttachmentBar');\n    let pendingAttachments = [];\n\n    function renderPendingAttachments() {\n      if (!pendingAttachments.length) {\n        pendingAttachmentBar.hidden = true;\n        pendingAttachmentBar.innerHTML = '';\n        return;\n      }\n      pendingAttachmentBar.innerHTML = pendingAttachments.map((att, i) => {\n        const ext = fileExt(att.name);\n        return `\n          <div class=\"msgs-pending-attachment-tile\">\n            <span class=\"msgs-pending-attachment-tile-name\">${escapeHtml(att.name)}</span>\n            <span class=\"msgs-pending-attachment-tile-ext\">${escapeHtml(ext)}</span>\n            <button type=\"button\" class=\"msgs-pending-attachment-tile-remove\" aria-label=\"Remove ${escapeHtml(att.name)}\" data-index=\"${i}\">\n              <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M6 6l12 12M18 6L6 18\"/></svg>\n            </button>\n          </div>\n        `;\n      }).join('');\n      pendingAttachmentBar.hidden = false;\n    }\n    // Delegated (not per-tile) since tiles are rebuilt on every add/remove.\n    pendingAttachmentBar.addEventListener('click', e => {\n      const btn = e.target.closest('.msgs-pending-attachment-tile-remove');\n      if (!btn) return;\n      pendingAttachments.splice(Number(btn.dataset.index), 1);\n      renderPendingAttachments();\n    });\n    attachBtn.addEventListener('click', () => {\n      // Signed in, messages are text only for now (2026-10-06): say so and\n      // add nothing.\n      if (MSG_LIVE) { showComposerNote(\"Attachments aren't supported yet. Paste a link instead.\"); return; }\n      attachFileInput.click();\n    });\n    attachFileInput.addEventListener('change', () => {\n      const files = Array.from(attachFileInput.files);\n      attachFileInput.value = ''; // so picking the same file(s) again still fires \"change\"\n      if (!files.length) return;\n      files.forEach(file => pendingAttachments.push({ kind: 'doc', name: file.name }));\n      renderPendingAttachments();\n    });\n\n    // Renders the small attachment chip under a message that carries one\n    // (see attachmentsOf() above and the `attachment`/`attachments`\n    // fields on CONVERSATIONS messages) — reuses the same file/media\n    // chip look the search panel uses (fileExt/fileExtColor/ICON_* are\n    // defined further down but already initialized by the time any\n    // message actually renders). A message with several attachments\n    // (2026-09-04) renders one of these chips per attachment, stacked.\n    // standaloneLabel/standaloneSentAt: passed only for the LAST\n    // attachment of a message that has no text bubble (attachment(s)\n    // sent with an empty message box, via the composer's attach button)\n    // — the timestamp that would normally sit inside the bubble is shown\n    // as its own small caption under that last chip instead, so it isn't\n    // lost, and isn't repeated under every chip when there are several.\n    // Fixed 2026-09-08 (Martin: \"links in messages... are not openable\" /\n    // \"files in messages... are not downloadable\"): this chip used to be\n    // pure static HTML with no click behavior at all — a real click did\n    // nothing, regardless of what the attachment was. It's now a real\n    // button, keyed by the same data-kind/data-name/data-url/data-title it\n    // carries here, opened by the delegated handler on #threadBubbles\n    // below (attachmentClickHandler).\n    function renderBubbleAttachment(a, standaloneLabel, standaloneSentAt) {\n      if (!a) return '';\n      let chip, dataAttrs;\n      if (a.kind === 'doc') {\n        const ext = fileExt(a.name);\n        chip = `<span class=\"msgs-file-chip\" style=\"background:${fileExtColor(ext)}\" aria-hidden=\"true\">${escapeHtml(ext)}</span><span class=\"msgs-bubble-attachment-text\"><span class=\"msgs-bubble-attachment-name\">${escapeHtml(a.name)}</span></span>`;\n        dataAttrs = `data-kind=\"doc\" data-name=\"${escapeHtml(a.name)}\"`;\n      } else if (a.kind === 'link') {\n        chip = `<span class=\"msgs-media-chip\" aria-hidden=\"true\">${ICON_LINK}</span><span class=\"msgs-bubble-attachment-text\"><span class=\"msgs-bubble-attachment-name msgs-bubble-attachment-name-link\">${escapeHtml(a.title)}</span></span>`;\n        dataAttrs = `data-kind=\"link\" data-url=\"${escapeHtml(a.url)}\"`;\n      } else if (a.kind === 'video' || a.kind === 'audio') {\n        chip = `<span class=\"msgs-media-chip\" aria-hidden=\"true\">${a.kind === 'video' ? ICON_VIDEO : ICON_AUDIO}</span><span class=\"msgs-bubble-attachment-text\"><span class=\"msgs-bubble-attachment-name\">${escapeHtml(a.name)}</span><span class=\"msgs-bubble-attachment-meta\">${escapeHtml(a.duration)}</span></span>`;\n        dataAttrs = `data-kind=\"${escapeHtml(a.kind)}\" data-name=\"${escapeHtml(a.name)}\"`;\n      } else {\n        return '';\n      }\n      const timeHtml = standaloneLabel ? timeSpanHtml(standaloneLabel, standaloneSentAt, 'msgs-bubble-attachment-time') : '';\n      return `<div class=\"msgs-bubble-attachment\" role=\"button\" tabindex=\"0\" ${dataAttrs}>${chip}</div>${timeHtml}`;\n    }\n\n    // A doc/video/audio attachment has no real file behind it — same\n    // \"no backend to store real bytes yet\" situation as /course-materials\n    // — so \"download\" is a real download of a small placeholder text blob\n    // naming the real attachment, not a dead link. Mirrors\n    // /course-materials's downloadPlaceholderFile() exactly.\n    function downloadPlaceholderAttachment(name) {\n      const content = `${name}\\n\\nThis is a placeholder file from the Averages mockup — no real file content is stored yet.\\nReal file delivery is coming with the Drive/Canva integrations (Release 1.0.0).`;\n      const blob = new Blob([content], { type: 'text/plain' });\n      const url = URL.createObjectURL(blob);\n      const a = document.createElement('a');\n      a.href = url;\n      a.download = name;\n      document.body.appendChild(a);\n      a.click();\n      document.body.removeChild(a);\n      setTimeout(() => URL.revokeObjectURL(url), 1000);\n    }\n    function openBubbleAttachment(el) {\n      const kind = el.dataset.kind;\n      if (kind === 'link') {\n        let url = el.dataset.url || '';\n        if (url && !/^https?:\\/\\//i.test(url)) url = `https://${url}`;\n        window.open(url, '_blank', 'noopener,noreferrer');\n      } else if (kind === 'doc' || kind === 'video' || kind === 'audio') {\n        downloadPlaceholderAttachment(el.dataset.name);\n      }\n    }\n    // Delegated on #threadBubbles so it covers every attachment in both the\n    // normal single-thread view and the merged \"All subjects\" timeline\n    // (both render into this same container) without needing to rewire\n    // anything on every re-render.\n    threadBubbles.addEventListener('click', e => {\n      // Signed in (2026-10-06): resend a message, or reload a thread.\n      const retry = e.target.closest('.msgs-retry-btn');\n      if (retry) { liveRetryMessage(retry.dataset.localId); return; }\n      const again = e.target.closest('[data-action=\"retry-thread\"]');\n      if (again) { liveRetryThread(again.dataset.id); return; }\n      const el = e.target.closest('.msgs-bubble-attachment');\n      if (el) openBubbleAttachment(el);\n    });\n    threadBubbles.addEventListener('keydown', e => {\n      if (e.key !== 'Enter' && e.key !== ' ') return;\n      const el = e.target.closest('.msgs-bubble-attachment');\n      if (!el) return;\n      e.preventDefault();\n      openBubbleAttachment(el);\n    });\n\n    // One message's markup -- shared by the normal single-thread view\n    // (renderBubbles) and the merged \"All subjects\" timeline\n    // (renderMergedBubbles below), so both stay in sync automatically.\n    function renderBubbleRowHtml(m, i, showAuthor) {\n      const atts = attachmentsOf(m);\n      const timeLabel = m.sentAt ? relativeTime(m.sentAt) : m.time;\n      const bubbleHtml = m.text ? `<div class=\"msgs-bubble\">${escapeHtml(m.text)}${timeSpanHtml(timeLabel, m.sentAt, 'msgs-bubble-time')}</div>` : '';\n      const attsHtml = atts.map((a, ai) => {\n        const isLast = ai === atts.length - 1;\n        return renderBubbleAttachment(a, (!m.text && isLast) ? timeLabel : '', (!m.text && isLast) ? m.sentAt : undefined);\n      }).join('');\n      // Signed in (2026-10-06): who wrote it in a group thread, and a\n      // message that didn't go through gets a Retry.\n      const authorHtml = showAuthor && m.from === 'them' && m.authorId ? `<span class=\"msgs-bubble-author\">${escapeHtml(personName(m.authorId))}</span>` : '';\n      const failedHtml = m.status === 'failed' ? `<div class=\"msgs-bubble-failed\" role=\"alert\"><span>${escapeHtml(m.error || \"Couldn't send.\")}</span>${m.canRetry === false ? '' : `<button type=\"button\" class=\"msgs-retry-btn\" data-local-id=\"${escapeHtml(m.localId)}\">Retry</button>`}</div>` : '';\n      return `\n        <div class=\"msgs-bubble-row ${escapeHtml(m.from)}\" data-msg-index=\"${i}\">\n          ${authorHtml}\n          ${bubbleHtml}\n          ${attsHtml}\n          ${failedHtml}\n        </div>\n      `;\n    }\n\n    function renderBubbles(c) {\n      // Signed in, a thread's messages load when it's opened (2026-10-06).\n      if (MSG_LIVE && c.load !== 'ready') { threadBubbles.innerHTML = liveThreadStateHtml(c); return; }\n      const showAuthors = MSG_LIVE && threadHasSeveralAuthors(c);\n      threadBubbles.innerHTML = c.messages.map((m, i) => renderBubbleRowHtml(m, i, showAuthors)).join('');\n      threadBubbles.scrollTop = threadBubbles.scrollHeight;\n    }\n\n    // Merged \"All subjects\" timeline (2026-09-04, per Martin: the top\n    // option in the subject dropdown) -- every thread with one person,\n    // concatenated in CONVERSATIONS order, each group of messages headed\n    // by a small pill naming its subject (see .msgs-subject-divider) so\n    // it still reads clearly which conversation each message came from\n    // even though they're shown together. Read-only: see\n    // setComposerEnabled, called by showAllSubjectsFor right after this.\n    function renderMergedBubbles(threads) {\n      threadBubbles.innerHTML = threads.map(c => `\n        <div class=\"msgs-subject-divider\"><span>${escapeHtml(c.subject)}</span></div>\n        ${MSG_LIVE && c.load !== 'ready' ? liveThreadStateHtml(c, true) : c.messages.map((m, i) => renderBubbleRowHtml(m, i, MSG_LIVE && threadHasSeveralAuthors(c))).join('')}\n      `).join('');\n      threadBubbles.scrollTop = threadBubbles.scrollHeight;\n    }\n\n    // Shows a REAL (already-existing-or-just-created) conversation --\n    // restores the normal avatar/name header, in case a compose draft's\n    // To bar/Subject bar were showing instead (see startComposeMode/\n    // startNewThreadWith/resumeComposeMode below).\n    function showThread(c) {\n      const p = person(c);\n      threadEmpty.hidden = true;\n      threadActive.hidden = false;\n      toBar.hidden = true;\n      subjectBar.hidden = true;\n      threadIdentity.hidden = false;\n      threadAvatar.textContent = avatarInitial(p.name);\n      threadAvatar.style.background = avatarBg(p);\n      threadName.textContent = p.name;\n      threadCourse.textContent = p.course;\n      viewingAllSubjectsFor = null;\n      renderSubjectDropdown(c.personId, c.id);\n      // Signed in, replying waits until the thread has loaded (2026-10-06).\n      setComposerEnabled(!MSG_LIVE || c.load === 'ready', false);\n      if (MSG_LIVE) liveComposerPlaceholder(c);\n      renderBubbles(c);\n    }\n\n    // ------------------------------------------------------------------\n    // Subject dropdown + \"All subjects\" merged view (2026-09-04, per\n    // Martin: \"under the persons name... a down arrow on the subject...\n    // when clicked... every subject you messaged under and at the top an\n    // all subjects option\"). Lives entirely alongside showThread/\n    // openConversation above -- threadsForPerson/renderSubjectDropdown\n    // run every time a real thread opens, and showAllSubjectsFor is the\n    // merged view's own entry point, parallel to showThread.\n    // ------------------------------------------------------------------\n    function threadsForPerson(personId) {\n      return CONVERSATIONS.filter(c => c.personId === personId);\n    }\n\n    // activeThreadId: the currently-open thread's id, or null when the\n    // merged \"All subjects\" view is what's open.\n    function renderSubjectDropdown(personId, activeThreadId) {\n      const threads = threadsForPerson(personId);\n      threadSubjectTriggerLabel.textContent = activeThreadId === null\n        ? 'All subjects'\n        : (threads.find(t => t.id === activeThreadId) || {}).subject || '';\n      threadSubjectMenu.innerHTML = `\n        <button type=\"button\" class=\"msgs-thread-subject-menu-item all-subjects ${activeThreadId === null ? 'active' : ''}\" role=\"menuitem\" data-thread-id=\"__all__\">All subjects</button>\n        ${threads.map(t => `<button type=\"button\" class=\"msgs-thread-subject-menu-item ${t.id === activeThreadId ? 'active' : ''}\" role=\"menuitem\" data-thread-id=\"${escapeHtml(t.id)}\">${escapeHtml(t.subject)}</button>`).join('')}\n      `;\n      threadSubjectMenu.dataset.personId = personId;\n      threadSubjectRow.hidden = false;\n    }\n\n    function closeSubjectMenu() {\n      threadSubjectMenu.hidden = true;\n      threadSubjectTrigger.setAttribute('aria-expanded', 'false');\n    }\n\n    // Disables the composer while the merged \"All subjects\" view is open\n    // -- there's no single thread to append a reply to (sendComposerMessage\n    // already no-ops with activeConvoId left null, this just makes that\n    // visible instead of the composer silently doing nothing).\n    // showHint (2026-10-06): false keeps the All-subjects hint hidden while\n    // the composer waits for a live thread to load.\n    function setComposerEnabled(enabled, showHint) {\n      composerInput.disabled = !enabled;\n      attachBtn.disabled = !enabled;\n      sendBtn.disabled = !enabled;\n      composerHint.hidden = showHint === undefined ? enabled : !showHint;\n    }\n\n    function showAllSubjectsFor(personId) {\n      const p = TEACHERS[personId];\n      const threads = threadsForPerson(personId);\n      if (!p || !threads.length) return;\n      pendingThread = null;\n      activeConvoId = null;\n      viewingAllSubjectsFor = personId;\n      threads.forEach(t => { if (t.unread) t.unread = false; });\n      threadEmpty.hidden = true;\n      threadActive.hidden = false;\n      toBar.hidden = true;\n      subjectBar.hidden = true;\n      threadIdentity.hidden = false;\n      threadAvatar.textContent = avatarInitial(p.name);\n      threadAvatar.style.background = avatarBg(p);\n      threadName.textContent = p.name;\n      threadCourse.textContent = p.course;\n      renderSubjectDropdown(personId, null);\n      if (MSG_LIVE) liveLoadThreads(threads);\n      renderMergedBubbles(threads);\n      setComposerEnabled(false);\n      renderThreadList();\n      msgsShell.classList.add('thread-open');\n    }\n\n    threadSubjectTrigger.addEventListener('click', () => {\n      const opening = threadSubjectMenu.hidden;\n      if (opening) {\n        threadSubjectMenu.hidden = false;\n        threadSubjectTrigger.setAttribute('aria-expanded', 'true');\n      } else {\n        closeSubjectMenu();\n      }\n    });\n    threadSubjectMenu.addEventListener('click', e => {\n      const item = e.target.closest('.msgs-thread-subject-menu-item');\n      if (!item) return;\n      closeSubjectMenu();\n      const threadId = item.dataset.threadId;\n      if (threadId === '__all__') showAllSubjectsFor(threadSubjectMenu.dataset.personId);\n      else openConversation(threadId);\n    });\n    document.addEventListener('click', e => {\n      if (!threadSubjectMenu.hidden && !e.target.closest('.msgs-thread-subject-row')) closeSubjectMenu();\n    });\n    document.addEventListener('keydown', e => {\n      if (e.key === 'Escape' && !threadSubjectMenu.hidden) { closeSubjectMenu(); threadSubjectTrigger.focus(); }\n    });\n\n    function openConversation(id) {\n      const c = CONVERSATIONS.find(x => x.id === id);\n      if (!c) return;\n      pendingThread = null;\n      activeConvoId = id;\n      if (c.unread) c.unread = false;\n      if (MSG_LIVE) liveLoadThread(c);\n      showThread(c);\n      renderThreadList();\n      msgsShell.classList.add('thread-open');\n      composerInput.value = '';\n    }\n\n    // ------------------------------------------------------------------\n    // New Message redesign (2026-09-04, per Martin) — replaces the old\n    // single startNewThread(personId), which required a person to\n    // already be chosen (from a separate people-picker panel) before the\n    // thread panel would even open. Three entry points now:\n    //\n    //  - startComposeMode(): the \"+\" button. No recipient yet -- opens\n    //    with the To dropdown empty, for the user to pick from (see\n    //    populateToSelect()).\n    //  - startNewThreadWith(personId): a specific person already known\n    //    up front (currently only the Contacts deep-link -- see\n    //    handleComposeDeepLink further down). Skips the To dropdown\n    //    entirely and shows their identity normally, since asking the\n    //    user to re-pick someone they just clicked \"Message\" on would be\n    //    redundant. Still shows the required Subject field.\n    //  - resumeComposeMode(): re-opens the thread panel on an\n    //    already-in-progress draft (pendingThread already set) without\n    //    resetting anything -- used when the pinned \"New Message\" row\n    //    (see newMessageRowHtml()) is clicked again, e.g. after using the\n    //    mobile back button.\n    //\n    // None of these add anything to CONVERSATIONS -- that only happens\n    // once the composer is actually submitted (see sendComposerMessage()).\n    // ------------------------------------------------------------------\n    // Search-as-you-type replacement for the old \"every person in the\n    // district in one dropdown\" picker (2026-09-05, per Martin: a real\n    // district's directory can run into the hundreds of people, so\n    // dumping the whole thing into one list doesn't scale and risks\n    // overflowing the page). Matches anywhere in the name, case-\n    // insensitive, and is capped to MAX_TO_RESULTS so the results box has\n    // a fixed, predictable size no matter how many people match or how\n    // big the district is.\n    const MAX_TO_RESULTS = 6;\n\n    function directoryMatches(query) {\n      const q = query.trim().toLowerCase();\n      if (!q) return [];\n      // Signed in: teachers, then whoever else Schoology lets them message.\n      if (MSG_LIVE) return liveDirectoryMatches(q);\n      return Object.entries(TEACHERS)\n        .filter(([, p]) => p.name.toLowerCase().includes(q))\n        .sort((a, b) => a[1].name.localeCompare(b[1].name))\n        .slice(0, MAX_TO_RESULTS);\n    }\n\n    let toHighlightIndex = -1;\n\n    function closeToResults() {\n      toResults.hidden = true;\n      toResults.innerHTML = '';\n      toHighlightIndex = -1;\n      toInput.setAttribute('aria-expanded', 'false');\n    }\n\n    function renderToResults(query) {\n      if (!query.trim()) { closeToResults(); return; }\n      const matches = directoryMatches(query);\n      toHighlightIndex = matches.length ? 0 : -1;\n      toResults.innerHTML = matches.length\n        ? matches.map(([id, p], i) => `\n            <button type=\"button\" class=\"msgs-to-result-item${i === 0 ? ' highlighted' : ''}\" role=\"option\" data-id=\"${escapeHtml(id)}\">\n              <span class=\"msgs-to-result-name\">${escapeHtml(p.name)}</span>\n              ${p.course ? `<span class=\"msgs-to-result-course\">${escapeHtml(p.course)}</span>` : ''}\n            </button>\n          `).join('')\n        : `<p class=\"msgs-to-no-results\">${MSG_LIVE ? liveNoMatchText(query.trim()) : `No one in the district matches \"${escapeHtml(query.trim())}\".`}</p>`;\n      toResults.hidden = false;\n      toInput.setAttribute('aria-expanded', 'true');\n    }\n\n    function selectToPerson(id) {\n      const p = TEACHERS[id];\n      if (!p || !pendingThread) return;\n      pendingThread.personId = id;\n      toInput.value = p.name;\n      toInput.classList.add('msgs-to-selected');\n      closeToResults();\n      threadBubbles.innerHTML = draftBubblesPlaceholder();\n    }\n\n    // Contact info popup, opened by clicking the To box once a recipient is\n    // selected (see the toInput click listener below) — fixes Martin's\n    // report that clicking a selected recipient's name did nothing (an\n    // <input>'s value is plain text; there was nothing to click). Same\n    // .modal-overlay convention as /contacts's own contact detail\n    // modal — see that file's openContactModal() for the twin.\n    const toContactModal = document.getElementById('toContactModal');\n    function openToContactModal(id) {\n      const c = CONTACTS.find(x => x.id === id);\n      const t = TEACHERS[id];\n      if (!c && !t) return;\n      document.getElementById('toContactModalAvatar').textContent = avatarInitial((c || t).name);\n      document.getElementById('toContactModalAvatar').style.background = (c || t).color;\n      document.getElementById('toContactModalName').textContent = (c || t).name;\n      document.getElementById('toContactModalRole').textContent = c ? (c.role || c.dept) : t.course;\n      document.getElementById('toContactModalDept').textContent = c ? c.dept : t.course;\n      // Signed in, someone who isn't a teacher has no class to show (2026-10-06).\n      if (MSG_LIVE) document.getElementById('toContactModalDept').parentElement.hidden = !(c ? c.dept : t.course);\n      // Only someone in the full district directory has a real record on\n      // /contacts to deep-link to — a one-off recipient that arrived\n      // via a compose deep-link with no matching CONTACTS entry doesn't.\n      const viewBtn = document.getElementById('toContactModalViewBtn');\n      if (c) {\n        viewBtn.href = `/contacts?open=${encodeURIComponent(c.id)}`;\n        viewBtn.hidden = false;\n      } else {\n        viewBtn.hidden = true;\n      }\n      toContactModal.classList.add('show');\n      document.getElementById('toContactModalCloseBtn').focus();\n    }\n    function closeToContactModal() { toContactModal.classList.remove('show'); }\n    document.getElementById('toContactModalCloseBtn').addEventListener('click', closeToContactModal);\n    toContactModal.addEventListener('click', e => { if (e.target === toContactModal) closeToContactModal(); });\n    document.addEventListener('keydown', e => {\n      if (e.key === 'Escape' && toContactModal.classList.contains('show')) closeToContactModal();\n    });\n    toInput.addEventListener('click', () => {\n      if (pendingThread?.personId) openToContactModal(pendingThread.personId);\n    });\n\n    function draftBubblesPlaceholder() {\n      const p = pendingThread && pendingThread.personId ? TEACHERS[pendingThread.personId] : null;\n      return p\n        ? `<p class=\"msgs-empty-hint\">Start a new conversation with ${escapeHtml(p.name)}.</p>`\n        : `<p class=\"msgs-empty-hint\">Choose who to message, then start typing below.</p>`;\n    }\n\n    function startComposeMode() {\n      if (MSG_LIVE) { liveLoadRecipients(); liveComposerPlaceholder(null); }\n      activeConvoId = null;\n      viewingAllSubjectsFor = null;\n      pendingThread = { personId: null, subject: '' };\n      threadEmpty.hidden = true;\n      threadActive.hidden = false;\n      threadIdentity.hidden = true;\n      threadSubjectRow.hidden = true; // no existing subject to pick from yet -- see #subjectBar below instead\n      closeSubjectMenu();\n      setComposerEnabled(true);\n      toBar.hidden = false;\n      subjectBar.hidden = false;\n      toInput.value = '';\n      toInput.classList.remove('msgs-to-selected');\n      closeToResults();\n      subjectInput.value = '';\n      threadBubbles.innerHTML = draftBubblesPlaceholder();\n      renderThreadList();\n      msgsShell.classList.add('thread-open');\n      composerInput.value = '';\n      toInput.focus();\n    }\n\n    function startNewThreadWith(personId) {\n      const p = TEACHERS[personId];\n      if (!p) return;\n      if (MSG_LIVE) liveComposerPlaceholder(null);\n      activeConvoId = null;\n      viewingAllSubjectsFor = null;\n      pendingThread = { personId, subject: '' };\n      threadEmpty.hidden = true;\n      threadActive.hidden = false;\n      toBar.hidden = true;\n      subjectBar.hidden = false;\n      subjectInput.value = '';\n      threadIdentity.hidden = false;\n      threadSubjectRow.hidden = true; // no existing subject to pick from yet -- see #subjectBar below instead\n      closeSubjectMenu();\n      setComposerEnabled(true);\n      threadAvatar.textContent = avatarInitial(p.name);\n      threadAvatar.style.background = avatarBg(p);\n      threadName.textContent = p.name;\n      threadCourse.textContent = p.course ? `${p.course} · New message` : 'New message';\n      threadBubbles.innerHTML = draftBubblesPlaceholder();\n      renderThreadList();\n      msgsShell.classList.add('thread-open');\n      composerInput.value = '';\n      composerInput.focus();\n    }\n\n    function resumeComposeMode() {\n      if (!pendingThread) return;\n      if (MSG_LIVE) { liveLoadRecipients(); liveComposerPlaceholder(null); }\n      activeConvoId = null;\n      viewingAllSubjectsFor = null;\n      threadEmpty.hidden = true;\n      threadActive.hidden = false;\n      threadIdentity.hidden = true;\n      threadSubjectRow.hidden = true;\n      closeSubjectMenu();\n      setComposerEnabled(true);\n      toBar.hidden = false;\n      subjectBar.hidden = false;\n      toInput.value = pendingThread.personId ? TEACHERS[pendingThread.personId].name : '';\n      toInput.classList.toggle('msgs-to-selected', !!pendingThread.personId);\n      closeToResults();\n      subjectInput.value = pendingThread.subject || '';\n      threadBubbles.innerHTML = draftBubblesPlaceholder();\n      renderThreadList();\n      msgsShell.classList.add('thread-open');\n    }\n    toInput.addEventListener('input', () => {\n      if (!pendingThread) return;\n      // Typing invalidates whatever was previously selected -- you can't\n      // stay \"sending to\" someone whose name you've since edited away.\n      pendingThread.personId = null;\n      toInput.classList.remove('msgs-to-selected');\n      renderToResults(toInput.value);\n    });\n    toInput.addEventListener('focus', () => {\n      if (toInput.value.trim() && !pendingThread?.personId) renderToResults(toInput.value);\n    });\n    toInput.addEventListener('keydown', e => {\n      if (toResults.hidden) return;\n      const items = Array.from(toResults.querySelectorAll('.msgs-to-result-item'));\n      if (e.key === 'ArrowDown') {\n        e.preventDefault();\n        if (!items.length) return;\n        toHighlightIndex = (toHighlightIndex + 1) % items.length;\n        items.forEach((el, i) => el.classList.toggle('highlighted', i === toHighlightIndex));\n      } else if (e.key === 'ArrowUp') {\n        e.preventDefault();\n        if (!items.length) return;\n        toHighlightIndex = (toHighlightIndex - 1 + items.length) % items.length;\n        items.forEach((el, i) => el.classList.toggle('highlighted', i === toHighlightIndex));\n      } else if (e.key === 'Enter') {\n        e.preventDefault();\n        const target = items[toHighlightIndex] || items[0];\n        if (target) selectToPerson(target.dataset.id);\n      } else if (e.key === 'Escape') {\n        closeToResults();\n      }\n    });\n    toResults.addEventListener('click', e => {\n      const item = e.target.closest('.msgs-to-result-item');\n      if (!item) return;\n      selectToPerson(item.dataset.id);\n    });\n    document.addEventListener('click', e => {\n      if (!toResults.hidden && !e.target.closest('#toSearchWrap')) closeToResults();\n    });\n    subjectInput.addEventListener('input', () => {\n      if (pendingThread) pendingThread.subject = subjectInput.value;\n    });\n\n    // Scrolls to and briefly highlights a specific message within a\n    // conversation — used by the search panel so picking a message match\n    // jumps straight to it instead of just opening the thread at the\n    // bottom.\n    function jumpToMessage(id, msgIndex) {\n      openConversation(id);\n      requestAnimationFrame(() => {\n        const row = threadBubbles.querySelector(`[data-msg-index=\"${msgIndex}\"]`);\n        if (!row) return;\n        row.scrollIntoView({ block: 'center', behavior: 'smooth' });\n        row.classList.add('flash');\n        setTimeout(() => row.classList.remove('flash'), 1500);\n      });\n    }\n\n    // A \"Combined\" row (data-combined=\"1\") represents more than one\n    // subject thread with the same person -- opening it means the merged\n    // \"All subjects\" timeline (showAllSubjectsFor), same as picking \"All\n    // subjects\" from that person's own subject dropdown. A combined row\n    // for someone with only one thread (data-combined=\"0\", i.e. Combined\n    // mode simply hasn't changed anything for them) still just opens\n    // normally, same as clicking any other row -- routing that case\n    // through showAllSubjectsFor would needlessly disable the composer\n    // for a person who only has one conversation anyway.\n    function openThreadRow(row) {\n      if (row.dataset.id === '__new__') { resumeComposeMode(); return; } // the pinned New Message draft row\n      if (row.dataset.combined === '1') { showAllSubjectsFor(row.dataset.personId); return; }\n      openConversation(row.dataset.id);\n    }\n    threadList.addEventListener('click', e => {\n      const row = e.target.closest('.msgs-thread-row');\n      if (!row) return;\n      openThreadRow(row);\n    });\n    threadList.addEventListener('keydown', e => {\n      if (e.key !== 'Enter' && e.key !== ' ') return;\n      const row = e.target.closest('.msgs-thread-row');\n      if (!row) return;\n      e.preventDefault();\n      openThreadRow(row);\n    });\n\n    document.getElementById('threadBackBtn').addEventListener('click', () => {\n      msgsShell.classList.remove('thread-open');\n    });\n\n    // ------------------------------------------------------------------\n    // Pin / Delete context menu (2026-09-04, per Martin: right-click a\n    // conversation in the left-side list -- not the pinned \"New Message\"\n    // draft row -- add Pin/Unpin and Delete). Follows the same\n    // open/close + outside-click + Escape pattern as #filterMenu and\n    // #profileMenu further down, except this one is position:fixed and\n    // anchored to the click coordinates (it can be triggered from any\n    // row anywhere in the scrollable list, not a fixed wrapper).\n    // ------------------------------------------------------------------\n    const rowContextMenu = document.getElementById('rowContextMenu');\n    const rowContextPinBtn = document.getElementById('rowContextPinBtn');\n    const rowContextPinLabel = document.getElementById('rowContextPinLabel');\n    const rowContextDeleteBtn = document.getElementById('rowContextDeleteBtn');\n    let contextMenuConvoId = null;\n    // Signed in, Delete would only hide the thread here (Schoology keeps it\n    // and it'd be back next time), so it's not offered (2026-10-06).\n    if (MSG_LIVE) rowContextDeleteBtn.hidden = true;\n\n    function closeRowContextMenu() {\n      rowContextMenu.hidden = true;\n      contextMenuConvoId = null;\n    }\n\n    function openRowContextMenu(convoId, x, y) {\n      const c = CONVERSATIONS.find(v => v.id === convoId);\n      if (!c) return;\n      contextMenuConvoId = convoId;\n      rowContextPinLabel.textContent = c.pinned ? 'Unpin' : 'Pin';\n      rowContextMenu.hidden = false;\n      // Clamp inside the viewport -- measure only after un-hiding so\n      // offsetWidth/Height reflect the real rendered size.\n      const menuW = rowContextMenu.offsetWidth;\n      const menuH = rowContextMenu.offsetHeight;\n      const maxX = window.innerWidth - menuW - 8;\n      const maxY = window.innerHeight - menuH - 8;\n      rowContextMenu.style.left = `${Math.max(8, Math.min(x, maxX))}px`;\n      rowContextMenu.style.top = `${Math.max(8, Math.min(y, maxY))}px`;\n    }\n\n    threadList.addEventListener('contextmenu', e => {\n      const row = e.target.closest('.msgs-thread-row');\n      if (!row || row.dataset.id === '__new__') return; // never on the draft row\n      // Skip a genuinely-merged Combined row (more than one subject with\n      // this person) -- Pin/Delete would be ambiguous about which of\n      // their several threads it applies to. A Combined row for someone\n      // with only one thread is unaffected (data-combined=\"0\") and still\n      // gets the normal menu.\n      if (row.dataset.combined === '1') return;\n      e.preventDefault();\n      openRowContextMenu(row.dataset.id, e.clientX, e.clientY);\n    });\n\n    rowContextPinBtn.addEventListener('click', () => {\n      const c = CONVERSATIONS.find(v => v.id === contextMenuConvoId);\n      if (c) c.pinned = !c.pinned;\n      closeRowContextMenu();\n      renderThreadList();\n    });\n\n    rowContextDeleteBtn.addEventListener('click', () => {\n      const id = contextMenuConvoId;\n      closeRowContextMenu();\n      if (!id) return;\n      const idx = CONVERSATIONS.findIndex(v => v.id === id);\n      if (idx === -1) return;\n      CONVERSATIONS.splice(idx, 1);\n      if (activeConvoId === id) {\n        // The deleted conversation was open -- fall back to the empty\n        // state rather than leaving a dangling thread panel open.\n        activeConvoId = null;\n        threadActive.hidden = true;\n        threadEmpty.hidden = false;\n        msgsShell.classList.remove('thread-open');\n      }\n      renderThreadList();\n    });\n\n    document.addEventListener('click', e => {\n      if (!rowContextMenu.hidden && !e.target.closest('#rowContextMenu')) closeRowContextMenu();\n    });\n    document.addEventListener('keydown', e => {\n      if (e.key === 'Escape' && !rowContextMenu.hidden) closeRowContextMenu();\n    });\n    // Closes the menu on scroll rather than letting it float disconnected\n    // from the row it was opened on.\n    threadList.addEventListener('scroll', () => { if (!rowContextMenu.hidden) closeRowContextMenu(); });\n\n    // ------------------------------------------------------------------\n    // Link detection (2026-09-04, per Martin: \"when you type a link, make\n    // it have the blue color and the underline and when sent turn it\n    // into a link attachment\"). #composerInput stays a plain <input>\n    // (see the sandboxed-form comment above sendComposerMessage below)\n    // rather than becoming contenteditable, so this is a light heuristic\n    // rather than per-character styling: URL_RE matches ONE bare-ish URL\n    // (protocol optional, matching how every existing sample link\n    // attachment is already written -- e.g. \"phet.colorado.edu/titration\",\n    // no \"https://\"), and while typing, the whole input goes blue +\n    // underlined the moment its value looks like it contains one (see the\n    // 'input' listener right below composerInput's declaration further\n    // down). Only the FIRST match in a message is turned into an\n    // attachment; a message with more than one URL is a rarer case this\n    // mock doesn't handle specially.\n    // ------------------------------------------------------------------\n    const URL_RE = /\\b((?:https?:\\/\\/)?(?:www\\.)?[a-z0-9-]+(?:\\.[a-z0-9-]+)+(?:\\/[^\\s]*)?)\\b/i;\n    function extractLinkAttachment(text) {\n      const m = text.match(URL_RE);\n      if (!m) return { text, linkAttachment: null };\n      const url = m[0];\n      const remaining = (text.slice(0, m.index) + text.slice(m.index + url.length)).replace(/\\s+/g, ' ').trim();\n      return { text: remaining, linkAttachment: { kind: 'link', title: url, url } };\n    }\n    composerInput.addEventListener('input', () => {\n      composerInput.classList.toggle('msgs-composer-link-active', URL_RE.test(composerInput.value));\n    });\n\n    // sendComposerMessage() used to be a <form> \"submit\" handler. Changed\n    // 2026-09-04 (per Martin: sending \"doesn't work\" for him) -- he was\n    // viewing the page in a sandboxed preview iframe, and a sandboxed\n    // iframe without \"allow-forms\" blocks real <form> submission at the\n    // browser level before any JS runs (confirmed via a Playwright repro:\n    // Chrome logs \"Blocked form submission... sandboxed and the\n    // 'allow-forms' permission is not set\" and the submit event never\n    // fires at all, so e.preventDefault() never got a chance to matter).\n    // The composer markup is a plain <div> now (see the HTML comment\n    // above #composerForm), and this same logic runs off a direct\n    // function call instead -- from the Send button's click listener and\n    // the Enter-key listener on #composerInput just below -- which isn't\n    // form submission and isn't subject to that sandbox restriction.\n    // sentAt (real epoch ms, 2026-09-04 per Martin) drives the live-\n    // updating relative label (\"Just now\" → \"1 min ago\" → ...) -- see the\n    // relativeTime()/tickRelativeTimes() comment above escapeHtml(). The\n    // static `time: 'Just now'` string is still set alongside it as a\n    // harmless fallback/label for anything that doesn't know about\n    // sentAt, but every render path here prefers sentAt when present.\n    function sendComposerMessage() {\n      if (MSG_LIVE) { liveSendComposerMessage(); return; } // the real thing, 2026-10-06\n      const raw = composerInput.value.trim();\n      const { text, linkAttachment } = extractLinkAttachment(raw);\n      if (!text && pendingAttachments.length === 0 && !linkAttachment) return; // attachment(s)/link alone are a valid send, same as most messaging apps\n      const msg = { from: 'me', text, time: 'Just now', sentAt: Date.now() };\n      const attachments = pendingAttachments.slice();\n      if (linkAttachment) attachments.push(linkAttachment);\n      if (attachments.length) msg.attachments = attachments;\n      if (pendingThread) {\n        // A brand-new thread requires a recipient -- can't be sent until\n        // one's chosen from the To search (see startComposeMode/toInput\n        // above). Subject is required by the real Schoology API too\n        // (per Martin); this mock doesn't hard-block on a blank one, it\n        // just falls back to a generic label, same spirit as every other\n        // non-blocking validation choice in this app.\n        if (!pendingThread.personId) { toInput.focus(); return; }\n        const subject = (pendingThread.subject || '').trim() || 'New conversation';\n        const c = {\n          id: `${pendingThread.personId}-${Date.now()}`,\n          personId: pendingThread.personId,\n          subject,\n          unread: false,\n          messages: [msg],\n        };\n        Object.assign(c, deriveMedia(c));\n        CONVERSATIONS.unshift(c);\n        pendingThread = null;\n        activeConvoId = c.id;\n        composerInput.value = '';\n        composerInput.classList.remove('msgs-composer-link-active');\n        pendingAttachments = [];\n        renderPendingAttachments();\n        showThread(c); // restores the normal avatar/name header now that it's a real thread\n        renderThreadList();\n        return;\n      }\n      if (!activeConvoId) return;\n      const c = CONVERSATIONS.find(x => x.id === activeConvoId);\n      c.messages.push(msg);\n      Object.assign(c, deriveMedia(c)); // refresh docs/links/etc. so new attachment(s) show up in search right away\n      composerInput.value = '';\n      composerInput.classList.remove('msgs-composer-link-active');\n      pendingAttachments = [];\n      renderPendingAttachments();\n      renderBubbles(c);\n      renderThreadList();\n    }\n    sendBtn.addEventListener('click', sendComposerMessage);\n    composerInput.addEventListener('keydown', e => {\n      if (e.key === 'Enter') { e.preventDefault(); sendComposerMessage(); }\n    });\n\n    // ------------------------------------------------------------------\n    // Search — clicking/focusing the search box opens a categorized panel\n    // (Messages / Docs / Links / Video / Audio, per Martin's 2026-09-01\n    // request) instead of a single flat list. With no query it's a browse\n    // view of recent items in each category; typing filters every category\n    // at once and highlights the matched text, but the category headers\n    // stay put even when a category has zero matches, rather than the\n    // layout jumping around. If the query matches a teacher's name, every\n    // category scopes down to just that person's thread(s) instead of\n    // everyone's — same idea as Spotlight narrowing to one contact.\n    // ------------------------------------------------------------------\n    const msgsSearchInput = document.getElementById('msgsSearch');\n    const searchResults = document.getElementById('searchResults');\n\n    function highlightMatch(text, q) {\n      const idx = text.toLowerCase().indexOf(q.toLowerCase());\n      if (idx === -1) return escapeHtml(text);\n      return escapeHtml(text.slice(0, idx)) + '<mark>' + escapeHtml(text.slice(idx, idx + q.length)) + '</mark>' + escapeHtml(text.slice(idx + q.length));\n    }\n\n    function messageMatches(q) {\n      const results = [];\n      CONVERSATIONS.forEach(c => {\n        searchableMessages(c).forEach(item => {\n          if (item.m.text.toLowerCase().includes(q)) results.push(item);\n        });\n      });\n      return results;\n    }\n\n    function allDocs() { return CONVERSATIONS.flatMap(c => c.docs.map(d => ({ ...d, c }))); }\n    function allLinks() { return CONVERSATIONS.flatMap(c => c.links.map(l => ({ ...l, c }))); }\n    function allVideo() { return CONVERSATIONS.flatMap(c => c.video.map(v => ({ ...v, c }))); }\n    function allAudio() { return CONVERSATIONS.flatMap(c => c.audio.map(a => ({ ...a, c }))); }\n\n    function matchedPersonId(q) {\n      if (!q) return null;\n      // Signed in, only someone with a thread here (2026-10-06): the\n      // directory also holds everyone the student could message.\n      const hit = Object.entries(TEACHERS).find(([id, t]) => t.name.toLowerCase().includes(q) && (!MSG_LIVE || CONVERSATIONS.some(c => c.personId === id)));\n      return hit ? hit[0] : null;\n    }\n\n    function searchCategories(qRaw) {\n      const q = qRaw.trim().toLowerCase();\n      const personId = matchedPersonId(q);\n      if (personId) {\n        const scope = CONVERSATIONS.filter(c => c.personId === personId);\n        return {\n          personId, q,\n          messages: scope.flatMap(c => searchableMessages(c)).slice(-6).reverse(),\n          docs: scope.flatMap(c => c.docs.map(d => ({ ...d, c }))),\n          links: scope.flatMap(c => c.links.map(l => ({ ...l, c }))),\n          video: scope.flatMap(c => c.video.map(v => ({ ...v, c }))),\n          audio: scope.flatMap(c => c.audio.map(a => ({ ...a, c }))),\n        };\n      }\n      if (!q) {\n        return {\n          personId: null, q,\n          messages: CONVERSATIONS.map(c => searchableMessages(c).slice(-1)[0]).filter(Boolean).slice(0, 6),\n          docs: allDocs().slice(0, 4),\n          links: allLinks().slice(0, 4),\n          video: allVideo().slice(0, 4),\n          audio: allAudio().slice(0, 4),\n        };\n      }\n      return {\n        personId: null, q,\n        messages: messageMatches(q),\n        docs: allDocs().filter(d => d.name.toLowerCase().includes(q)),\n        links: allLinks().filter(l => l.title.toLowerCase().includes(q) || l.url.toLowerCase().includes(q)),\n        video: allVideo().filter(v => v.name.toLowerCase().includes(q)),\n        audio: allAudio().filter(a => a.name.toLowerCase().includes(q)),\n      };\n    }\n\n    function fileExt(name) { return name.split('.').pop().toUpperCase(); }\n    function fileExtColor(ext) {\n      if (ext === 'PDF') return '#b23b2e';\n      if (ext === 'DOCX') return '#2f5fa8';\n      if (ext === 'PPTX') return '#c07a1f';\n      return 'var(--accent)';\n    }\n    const ICON_LINK = '<span class=\"emo\"><svg aria-hidden=\"true\" focusable=\"false\" viewBox=\"0 0 36 36\"><path fill=\"#8899A6\" d=\"m15 9 6-6s6-6 12 0 0 12 0 12l-8 8s-6 6-12 0c-1.125-1.125-1.822-2.62-1.822-2.62l3.353-3.348S14.396 18.396 16 20c0 0 3 3 6 0l8-8s3-3 0-6-6 0-6 0l-3.729 3.729s-1.854-1.521-5.646-.354L15 9z\"/><path fill=\"#8899A6\" d=\"m20.845 27-6 6s-6 6-12 0 0-12 0-12l8-8s6-6 12 0c1.125 1.125 1.822 2.62 1.822 2.62l-3.354 3.349s.135-1.365-1.469-2.969c0 0-3-3-6 0l-8 8s-3 3 0 6 6 0 6 0l3.729-3.729s1.854 1.521 5.646.354l-.374.375z\"/></svg></span>';\n    const ICON_VIDEO = '<span class=\"emo\"><svg aria-hidden=\"true\" focusable=\"false\" viewBox=\"0 0 36 36\"><path fill=\"#3F7123\" d=\"M35.845 32c0 2.2-1.8 4-4 4h-26c-2.2 0-4-1.8-4-4V19c0-2.2 1.8-4 4-4h26c2.2 0 4 1.8 4 4v13z\"/><path fill=\"#3F7123\" d=\"M1.845 15h34v6h-34z\"/><path fill=\"#CCD6DD\" d=\"M1.845 15h34v7h-34z\"/><path fill=\"#292F33\" d=\"M1.845 15h4l-4 7v-7zm11 0-4 7h7l4-7h-7zm14 0-4 7h7l4-7h-7z\"/><path fill=\"#CCD6DD\" d=\"M.155 8.207 33.148 0l1.69 6.792L1.845 15z\"/><path fill=\"#292F33\" d=\"m.155 8.207 5.572 5.827L1.845 15 .155 8.207zm19.158 2.448-5.572-5.828-6.793 1.69 5.572 5.828 6.793-1.69zm13.586-3.38-5.572-5.828-6.793 1.69 5.572 5.827 6.793-1.689z\"/></svg></span>';\n    const ICON_AUDIO = '<span class=\"emo\"><svg aria-hidden=\"true\" focusable=\"false\" viewBox=\"0 0 36 36\"><path fill=\"#66757F\" d=\"M18 0C9.716 0 3 6.716 3 15v9h3v-9C6 8 11.269 2.812 18 2.812 24.73 2.812 30 8 30 15v10l3-1v-9c0-8.284-6.716-15-15-15z\"/><path fill=\"#31373D\" d=\"M6 27a2 2 0 0 1-2 2H2a2 2 0 0 1-2-2v-9a2 2 0 0 1 2-2h2a2 2 0 0 1 2 2v9zm30 0a2 2 0 0 1-2 2h-2a2 2 0 0 1-2-2v-9a2 2 0 0 1 2-2h2a2 2 0 0 1 2 2v9z\"/><path fill=\"#55ACEE\" d=\"m19.182 10.016-6.364 1.313c-.45.093-.818.544-.818 1.004v16.185a6.218 6.218 0 0 0-2.087-.36c-2.785 0-5.042 1.755-5.042 3.922 0 2.165 2.258 3.827 5.042 3.827C12.649 35.905 14.922 34 15 32V16.39l4.204-.872c.449-.093.796-.545.796-1.004v-3.832c0-.458-.368-.759-.818-.666zm8 3.151-4.297.865c-.45.093-.885.544-.885 1.003V26.44c0-.152-.878-.24-1.4-.24-2.024 0-3.633 1.276-3.633 2.852 0 1.574 1.658 2.851 3.683 2.851s3.677-1.277 3.677-2.851l-.014-11.286 2.869-.598c.45-.093.818-.544.818-1.003v-2.33c0-.459-.368-.76-.818-.668z\"/></svg></span>';\n    // Same glyph as #rowContextPinBtn's icon in the markup above -- kept\n    // in sync by hand since this one gets stamped into thread-row HTML\n    // by renderThreadList() while that one is static.\n    const ICON_PIN = '<span class=\"emo\"><svg aria-hidden=\"true\" focusable=\"false\" viewBox=\"0 0 36 36\"><path fill=\"#BE1931\" d=\"M23.651 23.297 12.702 12.348l9.386-7.821 9.385 9.385z\"/><path fill=\"#DD2E44\" d=\"M34.6 13.912a4.42 4.42 0 0 1-6.255 0l-6.257-6.256a4.426 4.426 0 0 1 6.257-6.258L34.6 7.656a4.423 4.423 0 0 1 0 6.256z\"/><path fill=\"#99AAB5\" d=\"M14 17.823S-.593 35.029.188 35.813C.97 36.596 18.177 22 18.177 22L14 17.823z\"/><path fill=\"#DD2E44\" d=\"M25.215 27.991a4.423 4.423 0 0 1-6.258 0L8.009 17.041a4.425 4.425 0 0 1 6.258-6.256l10.948 10.949a4.424 4.424 0 0 1 0 6.257z\"/></svg></span>';\n\n    function renderMsgItem({ c, i, m }, q) {\n      const p = person(c);\n      return `\n        <button class=\"msgs-search-result-row\" type=\"button\" data-kind=\"message\" data-id=\"${escapeHtml(c.id)}\" data-index=\"${i}\">\n          <span class=\"msgs-avatar\" style=\"width:32px;height:32px;font-size:0.78rem;background:${escapeHtml(avatarBg(p))}\">${escapeHtml(avatarInitial(p.name))}</span>\n          <span class=\"msgs-search-result-text\">\n            <span class=\"msgs-search-result-name\">${escapeHtml(p.name)}</span>\n            <span class=\"msgs-search-result-snippet\">${m.from === 'me' ? 'You: ' : ''}${q ? highlightMatch(m.text, q) : escapeHtml(m.text)}</span>\n          </span>\n        </button>`;\n    }\n    function renderDocItem(d, q) {\n      const p = person(d.c);\n      const ext = fileExt(d.name);\n      return `\n        <button class=\"msgs-search-result-row\" type=\"button\" data-kind=\"thread\" data-id=\"${escapeHtml(d.c.id)}\">\n          <span class=\"msgs-file-chip\" style=\"background:${fileExtColor(ext)}\" aria-hidden=\"true\">${escapeHtml(ext)}</span>\n          <span class=\"msgs-search-result-text\">\n            <span class=\"msgs-search-result-name\">${q ? highlightMatch(d.name, q) : escapeHtml(d.name)}</span>\n            <span class=\"msgs-search-result-snippet\">${escapeHtml(p.name)} · ${escapeHtml(d.time)}</span>\n          </span>\n        </button>`;\n    }\n    function renderLinkItem(l, q) {\n      const p = person(l.c);\n      const host = l.url.split('/')[0];\n      return `\n        <button class=\"msgs-search-result-row\" type=\"button\" data-kind=\"thread\" data-id=\"${escapeHtml(l.c.id)}\">\n          <span class=\"msgs-media-chip\" aria-hidden=\"true\">${ICON_LINK}</span>\n          <span class=\"msgs-search-result-text\">\n            <span class=\"msgs-search-result-name\">${q ? highlightMatch(l.title, q) : escapeHtml(l.title)}</span>\n            <span class=\"msgs-search-result-snippet\">${escapeHtml(p.name)} · ${escapeHtml(host)}</span>\n          </span>\n        </button>`;\n    }\n    function renderMediaItem(item, q, kind) {\n      const p = person(item.c);\n      return `\n        <button class=\"msgs-search-result-row\" type=\"button\" data-kind=\"thread\" data-id=\"${escapeHtml(item.c.id)}\">\n          <span class=\"msgs-media-chip\" aria-hidden=\"true\">${kind === 'video' ? ICON_VIDEO : ICON_AUDIO}</span>\n          <span class=\"msgs-search-result-text\">\n            <span class=\"msgs-search-result-name\">${q ? highlightMatch(item.name, q) : escapeHtml(item.name)}</span>\n            <span class=\"msgs-search-result-snippet\">${escapeHtml(p.name)} · ${escapeHtml(item.duration)}</span>\n          </span>\n        </button>`;\n    }\n    function renderCategorySection(title, items, renderItem, q) {\n      const body = items.length\n        ? items.map(renderItem).join('')\n        : `<p class=\"msgs-search-cat-empty\">${q ? 'No matches' : 'Nothing yet'}</p>`;\n      return `<div class=\"msgs-search-cat\"><h4 class=\"msgs-search-cat-title\">${title}</h4>${body}</div>`;\n    }\n\n    function renderSearchResults() {\n      const { personId, q, messages, docs, links, video, audio } = searchCategories(searchQuery);\n      const header = personId\n        ? `<div class=\"msgs-search-scope\">Showing results for <strong>${escapeHtml(TEACHERS[personId].name)}</strong></div>`\n        : '';\n      searchResults.innerHTML = header\n        + renderCategorySection('Messages', messages, item => renderMsgItem(item, q), q)\n        + renderCategorySection('Docs', docs, item => renderDocItem(item, q), q)\n        + renderCategorySection('Links', links, item => renderLinkItem(item, q), q)\n        + renderCategorySection('Video', video, item => renderMediaItem(item, q, 'video'), q)\n        + renderCategorySection('Audio', audio, item => renderMediaItem(item, q, 'audio'), q);\n      searchResults.hidden = false;\n    }\n\n    // ------------------------------------------------------------------\n    // Search mode (2026-09-01 rework): clicking/focusing the search field\n    // no longer opens a dropdown floating over the thread list — it\n    // swaps the categorized results panel in for the thread list, in the\n    // exact same slot (see .msgs-search-results next to #threadList in\n    // the HTML and CSS above). The search bar itself \"morphs\": the input\n    // is flex:1 inside .msgs-search-wrap, and the clear (X) button next\n    // to it animates its own width from 0 up — so as the X grows in, the\n    // input visibly shrinks to make room for it, while .msgs-search-wrap\n    // itself (sized by the header's flex row) never changes width. The X\n    // doubles as \"cancel search\": clicking it clears the query and\n    // restores the normal thread list, same as Escape or picking a\n    // result.\n    // ------------------------------------------------------------------\n    const searchWrap = document.getElementById('searchWrap');\n    const searchClearBtn = document.getElementById('searchClearBtn');\n    let searchActive = false;\n\n    function enterSearchMode() {\n      if (searchActive) return;\n      searchActive = true;\n      searchClearBtn.classList.add('show');\n      threadList.hidden = true;\n      renderSearchResults();\n    }\n    function exitSearchMode() {\n      searchActive = false;\n      searchClearBtn.classList.remove('show');\n      searchResults.hidden = true;\n      threadList.hidden = false;\n      searchQuery = '';\n      msgsSearchInput.value = '';\n    }\n\n    msgsSearchInput.addEventListener('focus', enterSearchMode);\n    msgsSearchInput.addEventListener('input', e => {\n      searchQuery = e.target.value;\n      if (!searchActive) enterSearchMode();\n      else renderSearchResults();\n    });\n    searchClearBtn.addEventListener('click', () => {\n      exitSearchMode();\n      msgsSearchInput.blur();\n    });\n    document.addEventListener('click', e => {\n      if (searchActive && !e.target.closest('#searchWrap') && !e.target.closest('#searchResults')) {\n        exitSearchMode();\n      }\n    });\n    document.addEventListener('keydown', e => {\n      if (e.key === 'Escape' && searchActive) { exitSearchMode(); msgsSearchInput.blur(); }\n    });\n    searchResults.addEventListener('click', e => {\n      const row = e.target.closest('.msgs-search-result-row');\n      if (!row) return;\n      if (row.dataset.kind === 'message') {\n        jumpToMessage(row.dataset.id, Number(row.dataset.index));\n      } else {\n        openConversation(row.dataset.id);\n      }\n      exitSearchMode();\n    });\n\n    const filterBtn = document.getElementById('filterBtn');\n    const filterMenu = document.getElementById('filterMenu');\n    function openFilterMenu() { filterMenu.hidden = false; filterBtn.setAttribute('aria-expanded', 'true'); }\n    function closeFilterMenu() { filterMenu.hidden = true; filterBtn.setAttribute('aria-expanded', 'false'); }\n    filterBtn.addEventListener('click', () => { if (filterMenu.hidden) openFilterMenu(); else closeFilterMenu(); });\n    document.addEventListener('click', e => { if (!filterMenu.hidden && !e.target.closest('.msgs-filter-wrap')) closeFilterMenu(); });\n    document.addEventListener('keydown', e => { if (e.key === 'Escape' && !filterMenu.hidden) { closeFilterMenu(); filterBtn.focus(); } });\n    document.querySelectorAll('.msgs-filter-item').forEach(item => {\n      item.addEventListener('click', () => {\n        currentFilter = item.dataset.filter;\n        document.querySelectorAll('.msgs-filter-item').forEach(i => i.classList.toggle('active', i === item));\n        renderThreadList();\n        closeFilterMenu();\n      });\n    });\n\n    renderThreadList();\n\n    // The \"+\" button starts a brand-new compose draft (see\n    // startComposeMode() above) — existing conversations stay visible in\n    // the list underneath it, per Martin's 2026-09-04 redesign (see the\n    // block comment above startComposeMode).\n    document.getElementById('composeBtn').addEventListener('click', startComposeMode);\n\n    // Signed in (2026-10-06): limits, the inbox's Try again, and Google\n    // Classroom's no-messages note.\n    if (MSG_LIVE) liveInit();\n\n    // ------------------------------------------------------------------\n    // Deep-link from /contacts (2026-09-02, per Martin's district\n    // directory — every contact gets a working Message button, not just\n    // current teachers): a contact card's Message button links here as\n    // /messages?compose=<id>, plus &name=/&dept=/&color= for anyone\n    // who isn't already one of this page's own TEACHERS. When <id> is a\n    // known teacher those extra params are ignored and the existing\n    // TEACHERS entry is used as-is; otherwise a TEACHERS entry is built\n    // from the URL params on the fly (same {name, course, color} shape\n    // every other entry has), so the rest of the app — avatarBg(),\n    // person(), the thread header, etc. — treats a district contact\n    // exactly like a current teacher without needing them hand-authored\n    // here. Either way this reuses startNewThreadWith(), so arriving via\n    // a deep link opens straight into that person's identity (no To\n    // dropdown needed — see the comment above startNewThreadWith).\n    // ------------------------------------------------------------------\n    (function handleComposeDeepLink() {\n      const params = new URLSearchParams(window.location.search);\n      const composeId = params.get('compose');\n      if (!composeId) return;\n      // Signed in, ids are Schoology's (2026-10-06): see liveComposeDeepLink.\n      if (MSG_LIVE) { liveComposeDeepLink(composeId, params); return; }\n      if (!TEACHERS[composeId]) {\n        const name = params.get('name');\n        if (!name) return; // not a known teacher and no fallback info to build one from\n        TEACHERS[composeId] = {\n          name,\n          course: params.get('dept') || '',\n          color: params.get('color') || '#83849a',\n        };\n      }\n      startNewThreadWith(composeId);\n    })();\n\n    // ------------------------------------------------------------------\n    // Nav — Home/Courses/Grades/Assignments are real pages now; Calendar/\n    // Settings stay visual-only placeholders, same convention used\n    // everywhere else in the app.\n    // ------------------------------------------------------------------\n    document.querySelectorAll('.nav-link').forEach(link => {\n      link.addEventListener('click', () => {\n        if (link.dataset.href) { window.location.href = link.dataset.href; return; }\n        document.querySelectorAll('.nav-link').forEach(l => l.classList.remove('active'));\n        link.classList.add('active');\n      });\n    });\n\n    // ------------------------------------------------------------------\n    // Profile menu — same behavior as every other page.\n    // ------------------------------------------------------------------\n    const profileBtn = document.getElementById('profileBtn');\n    // Shared profile photo/name (2026-09-07) — /settings's Edit\n    // Profile modal is the only place this is ever set, but every other\n    // page's top-right profile button used to just show a fixed \"M\" no\n    // matter what was saved there: the button never read anything back,\n    // so a photo you set in Settings was invisible the moment you left\n    // it. schoolagy_profile is the same localStorage record\n    // /settings writes on every save; this is read-only here.\n    (function () {\n      var profile = null;\n      try {\n        var raw = localStorage.getItem('schoolagy_profile');\n        if (raw) profile = JSON.parse(raw);\n      } catch (e) {}\n      if (!profile) return;\n      if (profile.photo) {\n        profileBtn.style.backgroundImage = 'url(\"' + profile.photo + '\")';\n        profileBtn.style.backgroundSize = 'cover';\n        profileBtn.style.backgroundPosition = 'center';\n        profileBtn.textContent = '';\n      } else if (profile.name) {\n        profileBtn.textContent = profile.name.trim().charAt(0).toUpperCase() || 'M';\n      }\n    })();\n    const profileMenu = document.getElementById('profileMenu');\n    function openProfileMenu() { profileMenu.hidden = false; profileBtn.setAttribute('aria-expanded', 'true'); }\n    function closeProfileMenu() { profileMenu.hidden = true; profileBtn.setAttribute('aria-expanded', 'false'); }\n    profileBtn.addEventListener('click', () => { if (profileMenu.hidden) openProfileMenu(); else closeProfileMenu(); });\n    document.addEventListener('click', e => { if (!profileMenu.hidden && !e.target.closest('.profile-menu-wrap')) closeProfileMenu(); });\n    document.addEventListener('keydown', e => { if (e.key === 'Escape' && !profileMenu.hidden) { closeProfileMenu(); profileBtn.focus(); } });\n    profileMenu.querySelectorAll('.profile-menu-item').forEach(item => {\n      item.addEventListener('click', () => {\n        if (item.dataset.action === 'settings') { window.location.href = '/settings'; return; }\n        closeProfileMenu();\n      });\n    });\n  \n\n\n    // Back link (2026-10-01, per Martin: \"where it returns to ... is always\n    // wrong\"). Every page records itself in a short per-tab trail; a page's\n    // back link then says and goes to the page before it (\"Back to AP\n    // Chemistry Hub\", \"Back to Grades\"...). With no trail (the page was\n    // opened directly) the page's own default back link is left alone.\n    (function () {\n      const SELF = '/messages';\n      const KEY = 'averages_nav_trail';\n      const here = SELF + location.search;\n      const label = (document.title || '').replace(/^Averages\\s*[—-]\\s*/, '') || 'Messages';\n      let trail = [];\n      try { trail = JSON.parse(sessionStorage.getItem(KEY) || '[]'); } catch {}\n      if (!Array.isArray(trail)) trail = [];\n      const last = trail[trail.length - 1];\n      if (last && last.href === here) last.label = label;                 // reload\n      else if (trail.length > 1 && trail[trail.length - 2].href === here) { trail.pop(); trail[trail.length - 1].label = label; } // went back\n      else trail.push({ href: here, label });\n      trail = trail.slice(-20);\n      try { sessionStorage.setItem(KEY, JSON.stringify(trail)); } catch {}\n\n      const btn = document.querySelector('.back-link');\n      const prev = trail[trail.length - 2];\n      if (!btn || !prev) return;\n      const fresh = btn.cloneNode(false);          // same button, minus old click handlers\n      fresh.removeAttribute('onclick');\n      const icon = btn.querySelector('svg');\n      if (icon) fresh.appendChild(icon.cloneNode(true));\n      const text = document.createElement('span');\n      text.textContent = 'Back to ' + prev.label;\n      fresh.appendChild(text);\n      fresh.addEventListener('click', () => { window.location.href = prev.href; });\n      btn.replaceWith(fresh);\n    })();\n  ";

export default function Page() {
  return (
    <LegacyPage
      title={TITLE}
      styleCss={STYLE_CSS}
      bodyHtml={BODY_HTML}
      scriptJs={SCRIPT_JS}
      requiresAuth={true}
      usesSavedTheme={true}
      hasUploads={false}
      externalScripts={[]}
      pageId={"messages"}
    />
  );
}
